export const catTuning = { ...CAT_DEFAULT_TUNING }

/**
 * Curva del salto con el gato del rig. p va de 0 a 1 (= 1 - a.hop): se agacha (flexiona las patas), salta,
 * va en el aire con las patas recogidas y cae flexionando otra vez. Devuelve la altura (metros) y la flexion.
 */
const smooth = (x) => x * x * (3 - 2 * x)
/** Levantar la pata sin esquinas: 0 mientras apoya y sube/baja suave (en vez de un corte brusco en 0). */
const liftCurve = (c) => (c <= 0 ? 0 : smooth(Math.min(1, c * 1.6)))
export function catJumpCurve(p) {
    const tune = catTuning
    if (p <= 0 || p >= 1) return { lift: 0, flex: 0 }
    if (p < 0.3) return { lift: 0, flex: tune.jumpCrouch * smooth(p / 0.3) }
    if (p < 0.8) {
        const u = (p - 0.3) / 0.5
        return {
            lift: Math.sin(u * Math.PI) * tune.jumpHeight,
            flex: tune.jumpCrouch + (tune.jumpAir - tune.jumpCrouch) * smooth(Math.min(1, u * 2.5)),
        }
    }
    const v = (p - 0.8) / 0.2
    return { lift: 0, flex: tune.jumpAir * (1 - smooth(v)) + tune.jumpLand * Math.sin(v * Math.PI) }
}
/** Cuanto avanza el salto por segundo (a.hop baja de 1 a 0). */
export const catJumpRate = () => 1 / Math.max(0.2, catTuning.jumpTime)

/** Un parpadeo. */
export function blinkCat(group) {
    group.userData.rig.blinkT = 0
}

// Mirar a la camara y ladrarle (solo en primera persona)
const LOOK_DISTANCE = 4.5 // a esta distancia (metros) el gato empieza a mirar a la camara
const BARK_DISTANCE = 3.2 // y a esta empieza a ladrarle cada pocos segundos
const BARK_EVERY = [10, 16] // segundos entre ladridos (minimo, maximo)
const MAX_YAW = 1.0 // cuanto puede girar la cabeza hacia los lados (radianes)
const MAX_PITCH = 0.6 // y hacia arriba / abajo
// Acicalarse (a.groom de 0 a 1): la pata delantera izquierda sube doblada hacia adelante (brazo, antebrazo y mano) y el cuello baja
// hacia ella (hueso 004, 005 y 006). Valores en radianes, probados en pantalla.
const GROOM_PAW = { 'ORG-upper_armL': -0.9, 'ORG-forearmL': 1.7, 'ORG-handL': 0.5 }
const GROOM_NECK = [0.2, 0.5, 0.7]
// cuanto se inclina (rx, radianes) y se mueve (dy arriba, dz al frente, en metros) el collar con a.groom = 1
export const GROOM_COLLAR = { rx: -0.5, dy: 0, dz: 0 }

/** Maullido: abre y cierra la mandibula (acompana al sonido audio.meow). */
export function meowCat(group) {
    group.userData.bark = 1
}

/**
 * Mueve los huesos cada cuadro. Lee lo que ya calcula updateCharacters:
 *   a.tail.rotation.z  vaiven de la cola      a.head.rotation.y / .z  mirada y cabeceo
 *   a.walking          camina                 a.hop                   salto (ladra)
 *   a.wag / a.shiver   alegria / miedo        a.eyes[0].scale         ojos grandes o entrecerrados
 * Ademas, en primera persona, cuando la camara se acerca el gato la mira de frente y le ladra.
 */
export function updateCatRig(group, dt) {
    const a = group.userData
    const rig = a.rig
    const t = state.time + a.ph
    const scared = clamp(a.shiver * 1.5, 0, 1)
    const petted = a.eyes[0].scale.x < 0.9 // ojos entrecerrados = lo estan acariciando
    const groom = a.groom || 0 // 0 a 1: se lame la pata (levanta una pata delantera y baja la cabeza)

    // ---- distancia a la camara
    // depuracion: con la animacion pausada solo se ve la pose manual
    if (rig.paused) {
        Object.values(rig.bones).forEach((e) => e.bone.quaternion.copy(e.rest))
        resetJaw(rig)
        applyManual(rig)
        return
    }

    const camera = catConfig.camera
    rig.bones['ORG-face'].bone.getWorldPosition(vHead)
    const dist = camera ? vHead.distanceTo(camera.position) : Infinity
    const fp = !!camera && (state.mode === 'fp' || catConfig.forceFp) && group.visible
    rig.look = damp(rig.look, fp && dist < LOOK_DISTANCE ? 1 : 0, 4, dt)

    // ---- caminar: patas en diagonal; la fase solo avanza mientras camina
    rig.walk = damp(rig.walk, a.walking ? 1 : 0, 8, dt)
    if (a.walking) rig.phase += dt * catTuning.walkSpeed * (a.run ? 1.7 : 1)
    const A = catTuning.walkThigh * rig.walk
    // flexion de las patas: la fija del panel, la del salto y la del susto (la mayor manda)
    const jump = a.hop > 0 ? catJumpCurve(1 - a.hop) : { lift: 0, flex: 0 }
    const tuneScared = catTuning.scaredCrouch * scared
    const flex = clamp(Math.max(catTuning.legFlex, jump.flex, tuneScared), 0, 1.5)
    rig.flex = damp(rig.flex || 0, flex, a.hop > 0 ? 40 : 10, dt)
    // el cuerpo sube y baja una vez por paso, en sintonia con las patas (suave, sin saltos)
    rig.bobY = catTuning.walkBob * (a.run ? 2.2 : 1) * rig.walk * (0.5 + 0.5 * Math.cos(2 * rig.phase))
    const F = rig.flex
    const tn = catTuning
    const leg = (thigh, shin, foot, phase, [kt, ks, kf], K, lift, footSign = 1) => {
        const s = Math.sin(phase)
        const f = F + lift
        pose(rig, thigh, K * A * s + f * kt)
        pose(rig, shin, K * A * tn.walkShin * liftCurve(-Math.cos(phase)) + f * ks)
        pose(rig, foot, -footSign * tn.walkFoot * K * A * s + f * kf)
    }
    const front = [tn.flexFrontThigh, tn.flexFrontShin, tn.flexFrontFoot]
    const hind = [tn.flexHindThigh, tn.flexHindShin, tn.flexHindFoot]
    const fk = tn.walkFrontK
    const hk = tn.walkHindK
    leg('ORG-upper_armL', 'ORG-forearmL', 'ORG-handL', -rig.phase, front, fk, tn.legLiftFL)
    leg('ORG-upper_armR', 'ORG-forearmR', 'ORG-handR', -rig.phase + Math.PI, front, fk, tn.legLiftFR)
    leg('ORG-thighL', 'ORG-shinL', 'ORG-footL', rig.phase + Math.PI, hind, hk, tn.legLiftHL, -1)
    if (groom > 0) for (const [bone, angle] of Object.entries(GROOM_PAW)) pose(rig, bone, angle * groom)
    leg('ORG-thighR', 'ORG-shinR', 'ORG-footR', rig.phase, hind, hk, tn.legLiftHR, -1)

    // ---- cola: vaiven lateral (mas fuerte hacia la punta) y metida entre las patas si tiene miedo
    // meneo constante en reposo y contento; solo con miedo se deja lo que calcula characters.js
    let wag = a.shiver > 0.3 ? a.tail.rotation.z : Math.sin(t * 3.2) * 0.32 * Math.max(1, a.wag)
    // asustado: la cola se desvia y gira de lado a lado (scaredTail*) mientras la cabeza se queda quieta
    wag +=
        scared *
        (catTuning.scaredTailSide + catTuning.scaredTailSwing * Math.sin(t * catTuning.scaredTailSpeed))
    pose(rig, 'ORG-tail004', scared * catTuning.scaredTailCurl, 0, wag * 0.5)
    pose(rig, 'ORG-tail003', scared * catTuning.scaredTailCurl * 0.5, 0, wag * 0.6)
    pose(rig, 'ORG-tail002', scared * catTuning.scaredTail, 0, wag * 0.8)
    pose(rig, 'ORG-tail001', scared * catTuning.scaredTail * 0.8, 0, wag)

    // ---- respiracion
    const bw = [
        [scared, 'Scared'],
        [clamp((a.wag - 1.8) / 0.6, 0, 1) * (1 - (rig.petted || 0)), 'Happy'],
        [rig.petted || 0, 'Pet'],
    ]
    let breathAmpK = 1
    let breathSpeedK = 1
    for (const [w, m] of bw) {
        breathAmpK += w * (catTuning['breath' + m + 'AmpK'] - 1)
        breathSpeedK += w * (catTuning['breath' + m + 'SpeedK'] - 1)
    }
    rig.breathPhase = (rig.breathPhase || 0) + dt * catTuning.breathSpeed * breathSpeedK
    const breath = Math.sin(rig.breathPhase) * catTuning.breathAmp * breathAmpK
    pose(rig, 'ORG-spine001', breath)
    pose(rig, 'ORG-spine002', breath)
    // el pecho se ensancha al inhalar (escala en X y Z, el hueso va a lo largo de Y)
    const chest = 1 + Math.sin(rig.breathPhase) * catTuning.breathChest * breathAmpK
    rig.bones['ORG-spine001'].bone.scale.set(chest, 1, chest)
    rig.bones['ORG-spine002'].bone.scale.set(chest, 1, chest)
    // las patas delanteras (hombros) y el cuello cuelgan de spine003: se deshace el giro de la respiracion ahi
    // para que solo se mueva el torso. q003 = inv(q002) * inv(q001) * rest001 * rest002 * rest003
    {
        const b6 = rig.bones['ORG-spine001']
        const b7 = rig.bones['ORG-spine002']
        const b8 = rig.bones['ORG-spine003']
        qTmp.copy(b7.bone.quaternion).invert()
        qBr.copy(b6.bone.quaternion).invert()
        qTmp.multiply(qBr).multiply(b6.rest).multiply(b7.rest).multiply(b8.rest)
        b8.bone.quaternion.copy(qTmp)
        b8.bone.scale.set(1 / (chest * chest), 1, 1 / (chest * chest)) // hombros y cuello sin deformar
        // y tambien su posicion: girar spine001/002 desplaza un poco el hombro (palanca), se devuelve a su sitio
        const p8 = (rig.p8 ||= b8.bone.position.clone())
        const q6 = b6.bone.quaternion
        const q7 = b7.bone.quaternion
        const target = vA.copy(p8).applyQuaternion(b7.rest).add(b7.bone.position).applyQuaternion(b6.rest)
        target.applyQuaternion(qBr.copy(q6).invert()).sub(b7.bone.position)
        b8.bone.position.copy(target.applyQuaternion(qTmp.copy(q7).invert()))
    }

    // ---- cabeza: la mirada normal (a.head) o, si la camara esta cerca, directo a la camara
    let yaw = a.head.rotation.y
    let pitch = 0
    if (rig.look > 0.01) {
        // direccion de la cabeza a la camara, vista desde el gato (z = frente, x = lado, y = arriba)
        vCam.copy(camera.position)
        group.worldToLocal(vCam)
        group.worldToLocal(vHead)
        const dx = vCam.x - vHead.x
        const dy = vCam.y - vHead.y
        const dz = vCam.z - vHead.z
        const toCamYaw = clamp(Math.atan2(dx, dz), -MAX_YAW, MAX_YAW)
        const toCamPitch = clamp(Math.atan2(dy, Math.hypot(dx, dz)), -MAX_PITCH, MAX_PITCH)
        yaw = yaw + (toCamYaw - yaw) * rig.look
        pitch = toCamPitch * rig.look
    }
    yaw *= 1 - scared * catTuning.scaredHeadLock // asustado: la cabeza no gira a los lados
    const roll = a.head.rotation.z * 3
    // el giro se reparte por el cuello; mirar arriba es un giro negativo en X
    // acicalandose: la cabeza baja hacia la pata y cabecea al lamer
    const lick = groom * (1 + 0.25 * Math.sin(t * 11))
    pose(rig, 'ORG-spine004', Math.sin(t * 1.3) * 0.03 - pitch * 0.2 + lick * GROOM_NECK[0], yaw * 0.3, 0)
    pose(rig, 'ORG-spine005', catTuning.scaredHead * scared - pitch * 0.3 + lick * GROOM_NECK[1], yaw * 0.3, 0)
    // la cabeza va un poco hacia adelante: se mueve el hueso del cuello a lo largo de "adelante"
    rig.bones['ORG-spine005'].bone.position
        .copy(rig.headFwd.restPos)
        .addScaledVector(rig.headFwd.dir, catTuning.headForward)
    pose(rig, 'ORG-spine006', catTuning.scaredHead * 0.8 * scared - pitch * 0.5 + lick * GROOM_NECK[2], yaw * 0.4, roll)

    // ---- ladrido: al saltar o, cerca de la camara, cada pocos segundos (con su sonido)
    const tune = catTuning
    if (fp && dist < BARK_DISTANCE && !petted && !a.walking && a.wag > 1.5) {
        rig.nextBark -= dt
        if (rig.nextBark <= 0) {
            rig.nextBark = BARK_EVERY[0] + Math.random() * (BARK_EVERY[1] - BARK_EVERY[0])
            a.bark = 1
            if (catConfig.sound) audio.meow()
        }
    }
    a.bark = Math.max(0, (a.bark || 0) - dt * tune.barkSpeed)
    // varias aperturas rapidas por cada ladrido (tune.barkBursts)
    // El maullido (audio.meow: un tono que sube y otro que baja, ~0.57 s en total): la boca se abre al empezar, se
    // mantiene abierta mientras suena y se cierra con el final del tono.
    const barkT = a.bark > 0 ? (1 - a.bark) / tune.barkSpeed : -1 // segundos desde que empezo el maullido
    const barkPulse = barkT < 0 ? 0 : smooth(Math.min(1, barkT / 0.14)) * (1 - smooth(Math.min(1, Math.max(0, (barkT - 0.3) / 0.27))))
    const bark = barkPulse * tune.jawOpen // al saltar no mueve la mandibula
    const jaw = bark
    const jawTotal = jaw

    // ---- ojos: grandes (susto) o, al acariciarlo, con el giro de parpados de pet*
    rig.petted = damp(rig.petted || 0, petted ? 1 : 0, 8, dt)
    // tamano del ojo: el de reposo (1); asustado solo cambia con scaredEyeScale. El tamano que ponen los pasos del
    // juego a los ojos (p. ej. 1.35 al asustarse) no se usa, para que el ojo asustado mida lo mismo que en reposo.
    const eyes = 1 + scared * (tune.scaredEyeScale - 1)
    ;['ORG-eyeL', 'ORG-eyeR'].forEach((name) => rig.bones[name]?.bone.scale.setScalar(eyes))
    // giro del ojo cuando esta asustado (el derecho es el reflejo del izquierdo)
    const eyeY = tune.scaredEyeY + tune.scaredEyeSwing * Math.sin(t * tune.scaredSwingSpeed + 0.6)
    pose(rig, 'ORG-eyeL', scared * tune.scaredEyeX, scared * eyeY, scared * tune.scaredEyeZ)
    pose(rig, 'ORG-eyeR', scared * tune.scaredEyeX, -scared * eyeY, -scared * tune.scaredEyeZ)

    // ---- parpados: parpadeo automatico (no mientras lo acarician) o el valor fijado en el panel
    if (!petted && tune.eyeBlinkEvery > 0) {
        rig.nextBlink -= dt
        if (rig.nextBlink <= 0) {
            rig.blinkT = 0
            rig.nextBlink = tune.eyeBlinkEvery * (0.6 + Math.random() * 0.8)
        }
    }
    rig.blinkT += dt / Math.max(0.05, tune.eyeBlinkTime)
    const blink = rig.blinkT < 1 ? Math.sin(rig.blinkT * Math.PI) : 0
    const closeL = rig.eyeForce.L ?? blink
    const closeR = rig.eyeForce.R ?? blink
    // izquierdo: el parpado de arriba baja con +Z y el de abajo sube con +X; el derecho es el reflejo (-Z)
    // el parpado hace el parpadeo y, ademas, cada estado (acariciado, contento, asustado) le suma su giro:
    // pet*, happy* y scared* en catTuning. El derecho es el reflejo del izquierdo (Y y Z al reves).
    const pt = rig.petted
    const happy = clamp((a.wag - 1.8) / 0.6, 0, 1) * (1 - pt)
    const mood = [
        [pt, 'pet'],
        [happy, 'happy'],
        [scared, 'scared'],
    ]
    const lid = (base, close, part, side) => {
        // base: giro del parpadeo (rad) en el eje que cierra; part: 'U' o 'L'
        const v = part === 'U' ? [0, 0, base * close * (1 - pt)] : [base * close * (1 - pt), 0, 0]
        for (const [w, m] of mood) {
            if (w <= 0) continue
            // contento: al parpadear el parpado vuelve a la pose de reposo y luego regresa a la de contento
            const k = m === 'happy' ? w * (1 - tune.happyBlinkReset * clamp(close, 0, 1)) : w
            v[0] += k * tune[m + part + 'X']
            v[1] += k * tune[m + part + 'Y']
            v[2] += k * tune[m + part + 'Z']
        }
        return side < 0 ? [v[0], -v[1], -v[2]] : v
    }
    const uL = lid(tune.eyeCloseUpper, closeL, 'U', 1)
    const uR = lid(tune.eyeCloseUpper, closeR, 'U', -1)
    const lL = lid(tune.eyeCloseLower, closeL, 'L', 1)
    const lR = lid(tune.eyeCloseLower, closeR, 'L', -1)
    pose(rig, 'ORG-lidTL', ...uL)
    pose(rig, 'ORG-lidBL', ...lL)
    pose(rig, 'ORG-lidTR', ...uR)
    pose(rig, 'ORG-lidBR', ...lR)
    // las cejas (arriba del ojo) se mueven igual que el parpado de arriba
    // El parpadeo junta los huesos: la base del parpado de arriba BAJA hasta el de abajo (que no se mueve).
    // lidUpDown sube o baja su posicion de reposo; las cejas lo siguen en eyeBrowK.
    const closeAmt = (c) => c * (1 - pt) + pt * tune.petLidClose
    const travelL = tune.lidTravel * closeAmt(closeL) - tune.lidUpDown
    const travelR = tune.lidTravel * closeAmt(closeR) - tune.lidUpDown
    for (const l of rig.lids) {
        const right = l.name.endsWith('R')
        const brow = l.name.includes('brow')
        const lower = l.name.startsWith('ORG-lidB')
        // el de abajo sube (hacia arriba = contra "down") solo si lidLowerTravel > 0; el de arriba baja con lidTravel
        const amount = lower
            ? -tune.lidLowerTravel * closeAmt(right ? closeR : closeL)
            : (right ? travelR : travelL) * (brow ? tune.eyeBrowK : 1)
        l.amount = amount // se aplica despues de la mandibula, que reinicia las cejas
    }
    ;['BL', 'TL'].forEach((n) => pose(rig, 'ORG-brow' + n, 0, 0, uL[2] * tune.eyeBrowK))
    ;['BR', 'TR'].forEach((n) => pose(rig, 'ORG-brow' + n, 0, 0, uR[2] * tune.eyeBrowK))

    // ---- orejas: cada estado suma su giro y su aleteo (earWalk*, earHappy*, earScared*, earPet*, earBark*)
    const earMood = [
        [rig.walk, 'Walk'],
        [happy, 'Happy'],
        [scared, 'Scared'],
        [pt, 'Pet'],
        [clamp(a.bark * 3, 0, 1), 'Bark'],
    ]
    let ex = 0
    let ey = 0
    let ez = 0
    for (const [w, m] of earMood) {
        if (w <= 0) continue
        ex += w * tune['ear' + m + 'X']
        ey += w * tune['ear' + m + 'Y']
        ez += w * (tune['ear' + m + 'Z'] + tune['ear' + m + 'Amp'] * Math.sin(t * tune['ear' + m + 'Speed']))
    }
    pose(rig, 'ORG-earL', ex, ey, ez)
    pose(rig, 'ORG-earR', ex, -ey, -ez) // reflejo

    // la mandibula se aplica al final, despues de las demas poses de la cara
    const jawAngle = catConfig.forceJaw ?? jawTotal
    applyJaw(rig, jawAngle)
    for (const l of rig.lids) l.bone.position.copy(l.restPos).addScaledVector(l.down, l.amount || 0)

    // la placa del collar se balancea con la gravedad (despues de mover los huesos)
    if (a.collar) {
        // mientras se lame la pata el cuello se dobla: el collar se inclina y se mueve para quedar pegado a la piel
        const u = a.collar.userData
        const rx = lick * GROOM_COLLAR.rx
        const dy = lick * GROOM_COLLAR.dy
        const dz = lick * GROOM_COLLAR.dz
        if (u.extraRx !== rx || u.extraDy !== dy || u.extraDz !== dz) {
            u.extraRx = rx
            u.extraDy = dy
            u.extraDz = dz
            refitCollar(a.collar)
        }
        updateCollarSwing(a.collar, dt)
    }

    // depuracion: pose manual encima de la animacion y lecturas para el panel
    applyManual(rig)

    // piso: el cuerpo baja o sube lo justo para que la pata mas baja toque el suelo (en el aire no)
    const inAir = a.hop > 0 && jump.lift > 0
    rig.drop = inAir ? 0 : lowestFoot(rig, group) - rig.restLow - catTuning.floorOffset
    rig.info = {
        dist,
        look: rig.look,
        walk: rig.walk,
        jaw: jawAngle,
        bark: a.bark,
        eyeL: closeL,
        eyeR: closeR,
        flex: rig.flex,
        hop: a.hop || 0,
        yawDeg: (yaw * 180) / Math.PI,
        pitchDeg: (pitch * 180) / Math.PI,
    }
}

/** Pose manual del panel de depuracion: { hueso: [x, y, z] } en radianes, sobre la pose de reposo. */
function applyManual(rig) {
    for (const [name, v] of Object.entries(rig.manual)) pose(rig, name, v[0], v[1], v[2])
}
