/**
 * INTERACCION: zonas donde aparece el boton 'E' y la baliza coral que guia al usuario.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { camera } from '../three/renderer.js'
import { player } from './player.js'
import { world } from '../three/world.js'

export function setBeacon(x, z, height, scale = 1) {
    let o = world.beacon
    if (x == null) {
        o.visible = false
        return
    }
    o.scale.setScalar(scale)
    o.userData.ring.visible = scale >= 1 // las marcas pequenas (kit, mascotas) son solo la flecha: sin el circulo del piso
    o.position.set(x, 0, z)
    o.visible = true
    o.userData.baseY = height ?? 1.2
}
export function setInteract(target) {
    state.interact = target
}
export function updateBeacon(dt) {
    let t = world.beacon
    if (t.visible) {
        t.userData.cone.position.y =
            (t.userData.baseY == null ? 1.2 : t.userData.baseY) + Math.sin(state.time * 3) * 0.15
        t.userData.ring.scale.setScalar(1 + Math.sin(state.time * 3) * 0.12)
    }
}
/** Objetivo de interaccion al alcance: state.interact puede ser uno o una lista (gana el mas cercano). */
function nearestInteract() {
    if (!state.interact || (state.mode !== 'fp' && state.mode !== 'tp')) return null
    const list = Array.isArray(state.interact) ? state.interact : [state.interact]
    let best = null
    let bestDist = Infinity
    list.forEach((target) => {
        const dist = Math.hypot(player.pos.x - target.x, player.pos.z - target.z)
        if (dist < target.r && dist < bestDist) {
            best = target
            bestDist = dist
        }
    })
    return best
}
const promptPoint = new THREE.Vector3()
/** El boton pequeno ("Revisar") aparece solo al acercarse, justo sobre el lugar de la busqueda; se activa con un clic (no hay tecla). */
export function updatePrompt() {
    const e = qs('#prompt')
    const target = nearestInteract()
    if (target) {
        qs('span', e).textContent = target.label
        e.hidden = false
        promptPoint.set(target.x, target.y ?? 0.9, target.z).project(camera)
        e.style.transform =
            'translate(' + ((promptPoint.x * 0.5 + 0.5) * innerWidth).toFixed(1) + 'px,' + ((-promptPoint.y * 0.5 + 0.5) * innerHeight).toFixed(1) + 'px) translate(-50%,-50%)'
    } else {
        e.hidden = true
    }
    return !!target
}
export function triggerInteract() {
    const target = nearestInteract()
    if (target) {
        audio.blip()
        if (!Array.isArray(state.interact)) state.interact = null
        target.fn()
    }
}
