/**
 * ESTADO GLOBAL compartido por toda la experiencia.
 * - state: paso actual, modo de camara, escena activa, tiempo.
 * - session: progreso del usuario (experiencias vistas, tamanos vistos...).
 */
export const state = {
    scene: null,
    mode: 'orbit',
    cur: null,
    curTick: null,
    curExit: null,
    interact: null,
    stepData: {},
    tipState: null,
    bgOverride: null,
    navTo: null, // { back, next }: acciones de la barra inferior Regresar / Siguiente
    showRot: 0,
    onDragStart: null,
    onDragEnd: null,
    onDrag: null, // (dx, dy) => ...: un paso puede usar el arrastre del puntero en lugar de girar la escena
    time: 0,
    lastBanner: '#',
    hideBanner: false, // true = el aviso del sismo se oculta (p. ej. al mostrar el resultado de una experiencia)
    onQuakePhase: function () {},
}
export const session = {
    done: new Set(),
    sizes: new Set(),
    greeted: false,
}
