/**
 * NAVEGACION entre pasos: registro `steps`, goTo(), transiciones y reinicio.
 * Cada paso vive en su archivo (intro, before, during, sizes, after, ending).
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { session, state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { fovBoost } from '../systems/camera.js'
import { camera } from '../three/renderer.js'
import { stopPetting } from '../systems/petting.js'
import { playWarp } from '../ui/warpFx.js'
import { player } from '../systems/player.js'
import { quake, stopQuake } from '../systems/quake.js'
import { resetBooks } from '../systems/quakeEffects.js'
import { cat, dog } from '../three/characters.js'
import { updateBanner } from '../ui/banner.js'
import { resetScreen } from '../ui/panels.js'
import { setStage } from '../ui/seismo.js'
import { openWardrobe } from '../three/thirdRoom.js'

function cleanupStep() {
    stopPetting() // la mano de las caricias solo se ve mientras se acaricia: al salir de un paso se esconde siempre
    openWardrobe(false, true) // el armario de la habitacion siempre empieza cerrado en cada paso
    if (state.curExit) {
        state.curExit()
        state.curExit = null
    }
    if (state.stepData.io) {
        state.stepData.io.disconnect()
        state.stepData.io = null
    }
    state.curTick = null
    state.onQuakePhase = function () {}
    state.stepData = {}
}
let fading = false
// Duracion (ms) del fundido a negro al llegar a cada paso; los demas usan 800
const FADE_MS = { quakeIntro: 1500, sizeIntro: 1200 }
// Teletransportacion: al usar Regresar / Siguiente (o las etapas de la linea de tiempo) el paso se abre como si se llegara a el
// de forma normal, sin importar donde estuviera la camara antes. Estos pasos parten de la pose de la camara (la leen al entrar),
// asi que aqui se pone la que tendria el usuario al llegar caminando: [posicion] y [hacia donde mira].
const ARRIVAL = {
    kit: { pos: [-0.55, 1.4, -2.05], look: [-1.75, 0.9, -2.15] }, // junto a la mesa del kit, mirandolo
    track: { pos: [1.5, 1.45, 1.15], look: [1.5, 0.8, 2.3] }, // frente al sofa, donde esperan Cacao y Nube
    trackCat: { pos: [1.5, 1.45, 1.15], look: [1.5, 0.8, 2.3] },
    antesEnd: { pos: [1.5, 1.45, 1.15], look: [1.5, 0.8, 2.3] },
}
function placeArrivalCamera(name) {
    const arrival = ARRIVAL[name]
    if (!arrival) return
    camera.position.set(...arrival.pos)
    camera.lookAt(...arrival.look)
    camera.updateMatrixWorld(true)
}
// Vista de frente al sofa, donde esperan Cacao y Nube: de ahi arranca el rastreo de cada una (siempre igual)
const FRONT_VIEW = { pos: new THREE.Vector3(1.5, 1.45, 1.15), look: new THREE.Vector3(1.5, 0.8, 2.3) }
const EASE_CSS = 'cubic-bezier(0.65, 0, 0.35, 1)' // easeInOutCubic para los fundidos de CSS
export function transitionTo(name, params, duration, teleport = false) {
    if (fading) return
    // de Cacao a Nube (o al reves) en el rastreo: directo, sin fundido y en un solo movimiento de camara continuo (de una a la otra)
    if ((state.cur === 'track' && name === 'trackCat') || (state.cur === 'trackCat' && name === 'track')) {
        state.keepFront = FRONT_VIEW.pos // enterStage conserva la camara pero deja la vista de frente al sofa
        try {
            goTo(name, params)
        } finally {
            state.keepFront = null
        }
        return
    }
    fading = true
    // el cierre llega con un amanecer: la pantalla se funde despacio a los colores del cierre, la camara se abre un poco y el cierre aparece
    // desvaneciendose (siempre igual, venga de donde venga)
    const dawn = name === 'close'
    const ms = dawn ? 1800 : teleport ? 850 : duration || FADE_MS[name] || 900
    let a = qs('#fade')
    a.classList.toggle('tele', teleport && !dawn) // la teletransportacion usa un fundido luminoso
    a.classList.toggle('dawn', dawn)
    a.style.transitionDuration = ms + 'ms'
    a.style.transitionTimingFunction = EASE_CSS // el fundido arranca y termina suave (easeInOutCubic)
    // los textos y botones del paso que se va se desvanecen primero (y los del nuevo aparecen con su propia entrada)
    document.body.classList.add('stageOut')
    a.classList.add('on')
    if (dawn) fovBoost.t = 0.5
    else if (teleport) audio.ding()
    setTimeout(() => {
        if (dawn) fovBoost.t = 0
        // si el paso falla al abrirse, el fundido igual se quita (antes la pantalla podia quedar trabada en negro)
        try {
            if (teleport) placeArrivalCamera(name)
            state.arrivedByTeleport = teleport // los pasos lo leen para empezar ya en su sitio (p. ej. con la puerta abierta)
            goTo(name, params)
        } catch (error) {
            console.error('No se pudo abrir el paso ' + name, error)
        }
        state.arrivedByTeleport = false
        document.body.classList.remove('stageOut')
        if (teleport && !dawn) {
            const flash = qs('#flash')
            flash.classList.remove('on')
            void flash.offsetWidth
            flash.classList.add('on')
        }
        // (con temporizadores y no con requestAnimationFrame: asi el fundido siempre se quita, aunque la pestana este en segundo plano)
        setTimeout(() => {
            a.classList.remove('on')
            setTimeout(() => {
                a.style.transitionDuration = ''
                a.style.transitionTimingFunction = ''
                a.classList.remove('tele', 'dawn')
                fading = false
            }, ms)
        }, (dawn ? 500 : teleport ? 120 : 250) + 50)
    }, ms)
}
/**
 * Transicion de "Iniciar simulacion": ondas de colores salen del boton, la camara se abre en un "zoom" y un iris
 * azul cubre la pantalla; detras arranca la introduccion y el iris se cierra hacia el centro para revelarla.
 */
let startWipeRunning = false
/**
 * Profundidad del iris azul: anillos de luz que vienen hacia la camara (un tunel) y nubes de humo que se abren
 * hacia los lados; al revelar la simulacion el iris no se cierra: se desvanece como una cortina de humo.
 */
function buildWipeDepth(iris) {
    if (iris.dataset.fx) return
    iris.dataset.fx = '1'
    const tunnel = document.createElement('div')
    tunnel.className = 'tunnel'
    for (let i = 0; i < 7; i++) {
        const ring = document.createElement('i')
        ring.style.setProperty('--d', i * 0.17 + 's')
        tunnel.appendChild(ring)
    }
    const smoke = document.createElement('div')
    smoke.className = 'smoke'
    for (let i = 0; i < 10; i++) {
        const a = (i / 10) * Math.PI * 2 + Math.random() * 0.4
        const dist = 34 + Math.random() * 22
        const puff = document.createElement('i')
        puff.style.setProperty('--dx', Math.cos(a) * dist + 'vmax')
        puff.style.setProperty('--dy', Math.sin(a) * dist * 0.8 + 'vmax')
        puff.style.setProperty('--s', 0.8 + Math.random() * 0.9)
        puff.style.setProperty('--dl', Math.random() * 0.35 + 's')
        smoke.appendChild(puff)
    }
    iris.append(tunnel, smoke)
}
export function playStartWipe(originEl) {
    if (startWipeRunning) return
    startWipeRunning = true
    const wipe = qs('#wipe')
    buildWipeDepth(qs('.iris', wipe))
    const box = originEl.getBoundingClientRect()
    wipe.style.setProperty('--x', box.left + box.width / 2 + 'px')
    wipe.style.setProperty('--y', box.top + box.height / 2 + 'px')
    wipe.className = 'on'
    wipe.offsetWidth
    wipe.classList.add('go')
    audio.whoosh()
    // efecto de avanzar en azul (estelas de luz y brillo sobre el tunel del iris); en su punto mas fuerte cambia de paso
    // y el iris se desvanece como una cortina de humo (ver css/15-transicion.css)
    playWarp({
        color: 'blue',
        inTime: 1.5,
        outTime: 3,
        onPeak: () => {
            goTo('start')
            wipe.classList.remove('go')
            wipe.classList.add('open')
        },
    })
    setTimeout(() => {
        wipe.className = ''
        startWipeRunning = false
    }, 5000)
}
/** Resuelve el destino de "Regresar" / "Siguiente": un nombre de paso o una funcion que lo calcula. */
function resolveTarget(target, params) {
    return typeof target === 'function' ? target(params) : target
}
/** Botones Regresar / Siguiente de la linea de tiempo: se actualizan en cada paso. */
function updateStepNav(name, step, params) {
    const back = qs('#navBack')
    const next = qs('#navNext')
    back.hidden = !step.prev
    next.hidden = !step.next
    // en el inicio no se muestra la navegacion
    qs('#navbar').classList.toggle('nav-off', name === 'home')
    state.navTo = {
        back: step.prev ? () => transitionTo(resolveTarget(step.prev, params), undefined, undefined, true) : null,
        next: step.next
            ? () => {
                  const to = resolveTarget(step.next, params)
                  if (typeof to === 'string') transitionTo(to, undefined, undefined, true)
              }
            : null,
    }
}
export function navGo(dir) {
    const go = state.navTo && state.navTo[dir]
    if (go) {
        audio.blip()
        go()
    }
}
export function goTo(name, params) {
    cleanupStep()
    resetScreen()
    player.locked = false
    state.bgOverride = null
    state.hideBanner = false
    let a = steps[name]
    if (!a) return
    state.cur = name
    state.lastBanner = '#'
    qs('#hud').hidden = name === 'home' && false
    // El sismo sigue durante toda la etapa 2 (tambien en los tamanos, mas suave); solo se reinicia en quakeIntro
    let o = a.stage === 2 && name !== 'quakeIntro'
    if (!o && quake.active) {
        stopQuake()
    }
    // Musica: tension suave desde la tarjeta que abre la etapa 2 hasta las experiencias; otra distinta en los tamanos
    const mood =
        a.stage === 2
            ? name === 'sizeOut'
                ? 'sizes' // al salir con las mascotas la musica se calma
                : name.startsWith('size')
                  ? 'suspense' // los tamanos mantienen la misma musica de las tres experiencias
                  : o || name === 'quakeIntro'
                  ? 'suspense'
                  : 'calm'
            : a.stage === 3
              ? 'hope'
              : 'calm'
    audio.setMood(mood)
    setStage(a.stage, a.w || 0)
    updateStepNav(name, a, params || {})
    a.enter(params || {})
    updateBanner()
}
function restartExperience() {
    stopQuake()
    resetBooks()
    session.done.clear()
    session.sizes.clear()
    session.greeted = false
    dog.visible = cat.visible = true
    goTo('home')
}
let wipeRunning = false
export function playRestartWipe(originEl) {
    if (wipeRunning) return
    wipeRunning = true
    let t = qs('#wipe'),
        a = originEl.getBoundingClientRect()
    t.style.setProperty('--x', a.left + a.width / 2 + 'px')
    t.style.setProperty('--y', a.top + a.height / 2 + 'px')
    t.className = 'on'
    t.offsetWidth
    t.classList.add('go')
    audio.whoosh()
    fovBoost.t = 1
    setTimeout(() => t.classList.add('hold'), 1e3)
    setTimeout(() => {
        restartExperience()
        fovBoost.t = 0
    }, 1750)
    setTimeout(() => {
        t.classList.remove('go', 'hold')
        t.classList.add('open')
    }, 2600)
    setTimeout(() => {
        t.className = ''
        wipeRunning = false
    }, 3900)
}
export const steps = {}
