/**
 * MODELO 3D del personaje que controla el usuario durante el sismo.
 */
import * as THREE from 'three'
import { cylinder, ellipsoid, place, roundedBox } from '../helpers.js'

export function createPerson() {
    let e = new THREE.Group(),
        t = '#f2c9a5',
        a = '#ff8a6f',
        o = '#2b4c8c',
        s = e.userData
    ;[-1, 1].forEach((r) => {
        let i = new THREE.Group()
        i.position.set(r * 0.11, 0.55, 0)
        // pierna con rodilla: el muslo gira desde la cadera y la pantorrilla desde la rodilla (para poder sentarse)
        i.add(place(cylinder(0.088, 0.09, 0.27, o, 12), 0, -0.135, 0))
        const knee = new THREE.Group()
        knee.position.set(0, -0.27, 0)
        knee.add(place(cylinder(0.085, 0.08, 0.25, o, 12), 0, -0.125, 0))
        knee.add(place(ellipsoid(0.1, '#ffffff', 1, 0.6, 1.4), 0, -0.25, 0.04))
        i.add(knee)
        e.add(i)
        if (r < 0) {
            s.legL = i
            s.kneeL = knee
        } else {
            s.legR = i
            s.kneeR = knee
        }
        let n = new THREE.Group()
        n.position.set(r * 0.27, 1.03, 0)
        n.add(place(cylinder(0.06, 0.06, 0.42, a, 10), 0, -0.19, 0))
        n.add(place(ellipsoid(0.065, t), 0, -0.42, 0))
        e.add(n)
        if (r < 0) {
            s.armL = n
        } else {
            s.armR = n
        }
    })
    e.add(place(cylinder(0.2, 0.22, 0.5, a, 16), 0, 0.82, 0))
    e.add(place(ellipsoid(0.21, a, 1, 0.55, 0.85), 0, 1.06, 0))
    e.add(place(ellipsoid(0.2, t), 0, 1.32, 0))
    e.add(place(ellipsoid(0.215, '#5a3a2a', 1, 0.75, 1.02), 0, 1.38, -0.03))
    ;[-1, 1].forEach((r) => e.add(place(ellipsoid(0.024, '#1c2233'), r * 0.075, 1.33, 0.18)))
    // la mochila: se puede ocultar (p. ej. al sentarse, para que no atraviese el respaldo)
    s.pack = place(roundedBox(0.3, 0.4, 0.15, 0.05, '#ffc24d'), 0, 0.86, -0.25)
    e.add(s.pack)
    return e
}
