    'Cuello y cabeza': ['ORG-spine009', 'ORG-spine010', 'ORG-spine011', 'ORG-face'],
    'Boca y lengua': ['ORG-jaw', 'ORG-tongue', 'ORG-tongue001', 'ORG-tongue002'],
