/**
 * ANIMACION "COMO CARGAR A UN PERRO" (pantalla de tamanos). El perro 3D toma la pose de cargado (cuerpo casi horizontal, cabeza arriba y
 * las patas colgando) y la persona que lo levanta es un DIBUJO (PNG de Illustrator: el cuerpo detras del perro y los brazos con manos por delante).
 *   - perro pequeno: se carga pegado al pecho, con la cabeza mas arriba
 *   - perro mediano / grande: se carga de lado, casi horizontal
 *
 * Los dibujos son sprites (siempre miran a la camara) puestos delante y detras del perro, asi se pueden ver desde varios lados al girar.
 *
 *   createCarryDemo({ dog (la mascota; tambien sirve el gato), kind: 'large' | 'small' | 'cat', home: {x, z} })  ->  { play(), update(dt), active, done, dispose(restore) }
 */
import * as THREE from 'three'
import { cat, dog as dogPet } from '../three/characters.js'
import { catTuning } from '../three/models/catGlb.js'
import { rigTuning } from '../three/models/dogGlb.js'
import { camera, mainScene } from '../three/renderer.js'

// Pose del perro en brazos: altura de su origen, cuanto sube la cabeza y que tan flexionadas cuelgan las patas (fracciones de la flexion
// maxima del rig); chest / rear = donde lo sostienen las manos (espacio del perro, antes de su escala; z es hacia su cabeza)
const CARRY = {
    large: { lift: 0.62, pitch: 0.16, front: 0.5, hind: 0.55, chest: [0, 0.36, 0.22], rear: [0, 0.38, -0.36], len: 1.5, bodyY: 0.5, who: 'dog' },
    small: { lift: 0.8, pitch: 0.5, front: 0.4, hind: 0.5, chest: [0, 0.36, 0.22], rear: [0, 0.38, -0.34], len: 1.5, bodyY: 0.5, who: 'dog' },
    // el gato (su modelo mide ~1 de largo, menos que el perro): se carga pegado al pecho, como el perro pequeno
    cat: { lift: 0.62, pitch: 0.45, front: 0.45, hind: 0.5, chest: [0, 0.27, 0.13], rear: [0, 0.28, -0.2], len: 1, bodyY: 0.35, who: 'cat' },
}
const ART = 2.4 // lado (m) de los sprites de la persona con el perro grande (con el pequeno es proporcional a su tamano)
const DOG_FORWARD = 0.3 // m: el perro se adelanta hacia la camara para no atravesar el dibujo del cuerpo (que queda pegado a la pared)
const BIG_DOG = 0.82 // escala del perro grande (ver sizes.js)
const ease = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}
const lerp = (a, b, k) => a + (b - a) * k

// ---------------------------------------------------------------- dibujos (PNG de Illustrator en static/)
// El cuerpo de la persona va detras del perro y los brazos (con las manos) por delante, como sprites que siempre miran a la camara.
// (alto / ancho de cada imagen; el perro pequeno tiene sus propios dibujos)
const ART_FILES = {
    large: { torso: 'carga-cuerpo.png', torsoAspect: 662 / 600, arms: 'carga-brazos.png', armsAspect: 198 / 622 },
    small: { torso: 'carga-cuerpo-pequeno.png', torsoAspect: 371 / 388, arms: 'carga-brazos-pequeno.png', armsAspect: 295 / 381 },
    cat: { torso: 'carga-cuerpo-gato.png', torsoAspect: 373 / 471, arms: 'carga-brazos-gato.png', armsAspect: 266 / 289 },
}
const textures = {}
const textureOf = (file) => {
    if (!textures[file]) {
        textures[file] = new THREE.TextureLoader().load(import.meta.env.BASE_URL + file)
        textures[file].colorSpace = THREE.SRGBColorSpace
    }
    return textures[file]
}

/**
 * Posicion de los dibujos y giro del perro, editables en vivo (se abre un panel abajo a la izquierda al desarrollar o con ?editar en la
 * direccion). Un juego de valores por tamano. Los desplazamientos (X a la derecha de la pantalla, Y hacia arriba) y los tamanos son
 * fracciones del lado del dibujo (asi acompanan al tamano del perro); los giros estan en radianes.
 */
const defaultsOf = (cfg) => ({
    dogYaw: Math.PI, // giro del perro (alrededor de la vertical)
    dogPitch: -cfg.pitch, // cabeza arriba o abajo
    dogRoll: 0, // inclinado hacia un lado
    torsoX: 0,
    torsoY: 0,
    torsoSize: 0.55,
    torsoRot: 0,
    armsX: 0,
    armsY: -0.12,
    armsSize: 0.6,
    armsRot: 0,
})
export const CARRY_DEFAULT = {}
export const carryTuning = {}
// ajustes de fabrica de cada uno
const LARGE_FIT = { dogYaw: 2.68, dogPitch: -0.03, dogRoll: 0, torsoX: 0.03, torsoY: -0.03, torsoSize: 0.48, torsoRot: 0, armsX: 0.01, armsY: -0.02, armsSize: 0.43, armsRot: 0 }
const SMALL_FIT = { dogYaw: 2.74, dogPitch: -0.72, dogRoll: -0.17, torsoX: -0.13, torsoY: -0.04, torsoSize: 0.52, torsoRot: 0, armsX: -0.12, armsY: -0.07, armsSize: 0.5, armsRot: 0 }
const CAT_FIT = { dogYaw: 3.12, dogPitch: -0.75, dogRoll: 0, torsoX: -0.02, torsoY: -0.1, torsoSize: 1.01, torsoRot: 0, armsX: -0.25, armsY: -0.17, armsSize: 0.48, armsRot: 0 }
const FITS = { large: LARGE_FIT, small: SMALL_FIT, cat: CAT_FIT }
Object.entries(CARRY).forEach(([kind, cfg]) => {
    CARRY_DEFAULT[kind] = { ...defaultsOf(cfg), ...(FITS[kind] || {}) }
    carryTuning[kind] = { ...CARRY_DEFAULT[kind] }
})
if (import.meta.env.DEV) {
    // (los ajustes guardados solo se leen en desarrollo: quien visita la pagina siempre ve los valores de arriba)
    try {
        const saved = JSON.parse(localStorage.getItem('petalert.carry') || '{}')
        Object.keys(carryTuning).forEach((kind) => saved[kind] && Object.assign(carryTuning[kind], saved[kind]))
    } catch (e) {}
}
const saveCarryTuning = () => {
    try {
        localStorage.setItem('petalert.carry', JSON.stringify(carryTuning))
    } catch (e) {}
}

const EDIT_FIELDS = [
    ['Perro', null],
    ['dogYaw', 'Giro (de lado a lado)', -6.3, 6.3],
    ['dogPitch', 'Cabeza arriba / abajo', -3.2, 3.2],
    ['dogRoll', 'Inclinacion lateral', -3.2, 3.2],
    ['Cuerpo de la persona (detras del perro)', null],
    ['torsoX', 'Izquierda / derecha', -1, 1],
    ['torsoY', 'Abajo / arriba', -1, 1],
    ['torsoSize', 'Tamano', 0.1, 1.5],
    ['torsoRot', 'Giro del dibujo', -3.2, 3.2],
    ['Brazos y manos (delante del perro)', null],
    ['armsX', 'Izquierda / derecha', -1, 1],
    ['armsY', 'Abajo / arriba', -1, 1],
    ['armsSize', 'Tamano', 0.1, 1.5],
    ['armsRot', 'Giro del dibujo', -3.2, 3.2],
]
function openCarryEditor(kind) {
    if (!import.meta.env.DEV && !/[?&]editar/.test(location.search)) return () => {}
    const tune = carryTuning[kind]
    const box = document.createElement('div')
    box.id = 'carryEditor'
    box.style.cssText =
        'position:fixed;left:14px;bottom:14px;z-index:9998;width:270px;max-height:calc(100vh - 28px);overflow-y:auto;padding:10px 12px;border-radius:12px;background:rgba(14,20,34,.93);color:#e8eefc;font:12px/1.4 system-ui,sans-serif;box-shadow:0 8px 30px rgba(0,0,0,.4)'
    box.innerHTML = '<b style="font-size:13px">Cargar: dibujos y perro</b>'
    const outputs = []
    EDIT_FIELDS.forEach(([key, label, min, max]) => {
        if (!label) {
            const h = document.createElement('div')
            h.textContent = key
            h.style.cssText = 'margin-top:10px;font-weight:600;color:#fff'
            box.appendChild(h)
            return
        }
        const row = document.createElement('label')
        row.style.cssText = 'display:flex;justify-content:space-between;margin-top:5px;color:#b9c6e4'
        const out = document.createElement('output')
        out.style.color = '#ffc24d'
        row.innerHTML = `<span>${label}</span>`
        row.appendChild(out)
        const input = document.createElement('input')
        Object.assign(input, { type: 'range', min, max, step: 0.01, value: tune[key] })
        input.style.cssText = 'width:100%'
        const show = () => (out.textContent = (+tune[key]).toFixed(2))
        input.addEventListener('input', () => {
            tune[key] = +input.value
            show()
            saveCarryTuning()
        })
        show()
        outputs.push(() => {
            input.value = tune[key]
            show()
        })
        box.append(row, input)
    })
    const button = (text, fn) => {
        const b = document.createElement('button')
        b.textContent = text
        b.style.cssText = 'margin:8px 6px 0 0;padding:4px 9px;border-radius:6px;border:1px solid #3e507a;background:#2a3856;color:#fff;cursor:pointer'
        b.addEventListener('click', fn)
        return b
    }
    box.append(
        button('Copiar valores', () => navigator.clipboard && navigator.clipboard.writeText(JSON.stringify({ [kind]: tune }, null, 2))),
        button('Restablecer', () => {
            Object.assign(tune, CARRY_DEFAULT[kind])
            outputs.forEach((fn) => fn())
            saveCarryTuning()
        }),
    )
    box.addEventListener('pointerdown', (e) => e.stopPropagation()) // el panel no gira la camara
    box.style.display = 'none' // se muestra y se oculta con la tecla M
    const toggle = (e) => {
        if (e.code === 'KeyM') box.style.display = box.style.display === 'none' ? '' : 'none'
    }
    addEventListener('keydown', toggle)
    document.body.appendChild(box)
    return () => {
        removeEventListener('keydown', toggle)
        box.remove()
    }
}

function makeSprite(file, order) {
    const sprite = new THREE.Sprite(
        new THREE.SpriteMaterial({ map: textureOf(file), transparent: true, opacity: 0, depthWrite: false, toneMapped: false, fog: false }),
    )
    sprite.renderOrder = order
    return sprite
}
// ---------------------------------------------------------------- animacion
export function createCarryDemo({ dog, kind, home }) {
    const cfg = CARRY[kind] || CARRY.large
    const demo = { active: false, done: false, time: 0 }
    const a = dog.userData
    const otherPet = () => (dog === cat ? dogPet : cat)
    const dogHome = new THREE.Vector3(home.x, 0, home.z)
    let homeYaw = 0
    let sprites = null
    let closeEditor = null
    const tune = carryTuning[kind] || carryTuning.large
    const files = ART_FILES[kind] || ART_FILES.large
    const right = new THREE.Vector3()
    const camDir = new THREE.Vector3()
    const center = new THREE.Vector3()
    let art = ART // lado de los dibujos de la persona (m), segun el tamano del perro

    demo.play = () => {
        if (!demo.active) {
            homeYaw = dog.rotation.y
            dog.rotation.order = 'YXZ'
        }
        if (!sprites) {
            art = ART * ((cfg.len * dog.scale.x) / (1.5 * BIG_DOG))
            sprites = { torso: makeSprite(files.torso, 4), arms: makeSprite(files.arms, 7) }
            sprites.arms.material.depthTest = false // los brazos siempre van por encima de la mascota (el gato, mas chico, los tapaba)
            mainScene.add(sprites.torso, sprites.arms)
        }
        demo.active = true
        demo.done = false
        demo.time = 0
        closeEditor?.()
        closeEditor = openCarryEditor(CARRY[kind] ? kind : 'large')
        otherPet().visible = false // la otra mascota se oculta mientras dura la demostracion: no se encima con el dibujo
        a.ty = null
        a.walking = false
    }

    demo.update = (dt) => {
        if (!demo.active) return
        demo.time += dt
        const t = demo.time
        const liftK = ease(t / 1.1)
        const artK = ease((t - 0.5) / 0.6)
        // el perro sube a la pose de cargado: gira de lado (la cabeza a la derecha de la pantalla), sube la cabeza y deja caer las patas
        // (se adelanta hacia la camara, en horizontal)
        const fx = camera.position.x - dogHome.x
        const fz = camera.position.z - dogHome.z
        const fl = Math.hypot(fx, fz) || 1
        a.base.set(dogHome.x + (fx / fl) * DOG_FORWARD * liftK, lerp(0, cfg.lift, liftK), dogHome.z + (fz / fl) * DOG_FORWARD * liftK)
        const yaw = tune.dogYaw
        a.faceTo = lerp(homeYaw, yaw, liftK)
        dog.rotation.y = lerp(homeYaw, yaw, liftK)
        dog.rotation.x = tune.dogPitch * liftK
        dog.rotation.z = tune.dogRoll * liftK
        const rig = a.rig
        if (rig?.manual) {
            // flexion de las patas colgando (las del perro y las del gato se llaman distinto y tienen su propia flexion maxima)
            const legs = {}
            if (cfg.who === 'cat') {
                const T = catTuning
                ;['L', 'R'].forEach((s) => {
                    legs[`ORG-upper_arm${s}`] = cfg.front * T.flexFrontThigh
                    legs[`ORG-forearm${s}`] = cfg.front * T.flexFrontShin
                    legs[`ORG-hand${s}`] = cfg.front * T.flexFrontFoot
                    legs[`ORG-thigh${s}`] = cfg.hind * T.flexHindThigh
                    legs[`ORG-shin${s}`] = cfg.hind * T.flexHindShin
                    legs[`ORG-foot${s}`] = cfg.hind * T.flexHindFoot
                })
            } else {
                const T = rigTuning
                ;['L', 'R'].forEach((s) => {
                    legs[`ORG-front_thigh${s}`] = cfg.front * T.flexFrontThigh
                    legs[`ORG-front_shin${s}`] = cfg.front * T.flexFrontShin
                    legs[`ORG-front_foot${s}`] = cfg.front * T.flexFrontFoot
                    legs[`ORG-thigh${s}`] = cfg.hind * T.flexHindThigh
                    legs[`ORG-shin${s}`] = cfg.hind * T.flexHindShin
                    legs[`ORG-foot${s}`] = cfg.hind * T.flexHindFoot
                })
            }            Object.entries(legs).forEach(([bone, angle]) => (rig.manual[bone] = [angle * liftK, 0, 0]))
        }
        if (liftK >= 1) demo.done = true
        // los dibujos: del lado de la camara y de su lado contrario, centrados en el perro
        if (sprites) {
            center.set(dogHome.x, cfg.lift + cfg.bodyY * dog.scale.x, dogHome.z) // (el centro del cuerpo del perro cargado)
            dog.updateMatrixWorld(true)
            camera.updateMatrixWorld(true)
            right.set(1, 0, 0).applyQuaternion(camera.quaternion)
            camDir.copy(center).sub(camera.position).normalize()
            const camDist = camera.position.distanceTo(center)
            // depth = cuanto se aparta de la camara (m, con la escala del dibujo); ref = la distancia con la que se ajusto el tamano
            const place = (sprite, part, aspect, depth, ref, alpha) => {
                const scale = art / ART
                const w = tune[part + 'Size'] * art * ((camDist + depth * scale) / (camDist + ref * scale)) // (a la misma distancia aparente)
                sprite.scale.set(w, w * aspect, 1)
                sprite.material.rotation = tune[part + 'Rot']
                sprite.position
                    .copy(center)
                    .addScaledVector(camDir, depth * scale)
                    .addScaledVector(right, tune[part + 'X'] * art)
                sprite.position.y += tune[part + 'Y'] * art
                sprite.material.opacity = artK * alpha
            }
            place(sprites.torso, 'torso', files.torsoAspect, 0.3, 0.3, 0.85) // detras del perro, un poco transparente
            place(sprites.arms, 'arms', files.armsAspect, -0.3 - DOG_FORWARD, -0.3, 1) // delante del perro (que se adelanto), sin transparencia
        }        a.walking = false
    }

    /** Quita los dibujos; con restore = true el perro vuelve a su lugar (al pasar a otra nota). */
    demo.dispose = (restore = false) => {
        if (sprites) {
            Object.values(sprites).forEach((s) => {
                s.removeFromParent()
                s.material.dispose() // (la textura se guarda para la proxima vez)
            })
            sprites = null
        }
        closeEditor?.()
        closeEditor = null
        if (!demo.active) return
        otherPet().visible = true
        if (restore) {
            a.base.set(dogHome.x, 0, dogHome.z)
            a.faceTo = homeYaw
            dog.rotation.y = homeYaw
        }
        demo.active = false
        dog.rotation.order = 'XYZ'
        dog.rotation.x = 0
        dog.rotation.z = 0
        const rig = a.rig
        if (rig?.manual) {
            ;['front_thigh', 'front_shin', 'front_foot', 'thigh', 'shin', 'foot', 'upper_arm', 'forearm', 'hand'].forEach((n) =>
                ['L', 'R'].forEach((s) => delete rig.manual[`ORG-${n}${s}`]),
            )
        }
    }
    return demo
}
