/**
 * PLANTILLAS de paso reutilizables: recorrido por hotspots y panel centrado.
 */
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { icon } from '../data/icons.js'
import { focusOn } from '../systems/camera.js'
import { addHotspot } from '../ui/hotspots.js'
import { showPanel } from '../ui/panels.js'

/**
 * Recorrido por hotspots: el usuario toca cada punto 3D y ve una tarjeta con su informacion.
 * Nada avanza solo: el usuario lee a su ritmo y pasa con "Siguiente".
 *
 * config:
 *   title, text      cabecera del panel
 *   items            [{ anchor, title, text, icon, rot }]
 *   zoom             distancia de la camara al acercarse a un punto
 *   onPick(i)        i = punto abierto, o -1 al volver a la vista general
 *   next()           paso siguiente (boton "Continuar" del panel, se activa al ver todos los puntos)
 *   backLabel        texto del unico boton de cada tarjeta (vuelve a la vista general, para escoger otro punto)
 *   autoNext         true = cada punto se marca como visto al cerrarlo (y se avisa con onSeen(i)).
 *   openFirst        true = abre el primer punto al entrar (sin temporizadores).
 *   sequential       true = el boton de cada tarjeta pasa directo al siguiente punto por ver (nextLabel / lastLabel en el ultimo).
 *   onOpen(i, item)  se llama al presentar cada punto (despues de armar la tarjeta); openDelay = ms antes de abrir el primero.
 *   noDots           true = los botones de los puntos no se ven ni se pueden tocar (solo se avanza con el boton de la tarjeta).
 *   fixedTip         true = la tarjeta va fija a la derecha de la pantalla (no pegada al punto).
 *   stepper          true = la tarjeta lleva Regresar (desde el segundo punto) y Continuar; en el ultimo, Listo (naranja), que llama
 *                    a config.finish(). Los puntos se recorren en orden (prevLabel, nextLabel y lastLabel cambian los textos).
 *   (item.focus      si un punto trae `focus`, la camara apunta ahi y no a `anchor`)
 *
 * Devuelve { buttons, seen, opened } (los botones de los hotspots y los puntos ya vistos/abiertos).
 */
export function startInfoTour(config) {
    const total = config.items.length
    const opened = new Set() // puntos que el usuario ya abrio
    const seen = new Set() // puntos que ya cerro (autoNext)
    const buttons = []
    const stepName = state.cur // para ignorar llamadas tardias si el usuario ya cambio de paso
    // onlyContinue: sin tarjeta de texto ni contador, solo el boton Continuar (abajo, al centro)
    const panel = showPanel(
        config.onlyContinue
            ? { cls: 'only', actions: [{ label: 'Continuar', fn: config.next }] }
            : {
                  title: config.title,
                  text: config.text,
                  html: '<p class="count"></p>',
                  actions: [{ label: 'Continuar', fn: config.next }],
              },
    )
    const count = qs('.count', panel)
    const tip = qs('#tip')

    // Continuar siempre esta disponible: si falta algo por ver, solo se avisa cuantos faltan
    const updateCount = () => {
        if (!count) return
        const n = config.autoNext ? seen.size : opened.size
        const missing = total - n
        count.textContent =
            missing > 0
                ? 'Faltan ' + missing + ' por descubrir · toca un punto para acercarte'
                : 'Ya descubriste los ' + total
    }
    // Cierra la tarjeta y vuelve a la vista general.
    const showAll = () => {
        state.tipState = null
        tip.hidden = true
        panel.hidden = !!(config.onlyContinue && !config.autoNext && opened.size < total) // solo Continuar: aparece al ver todos los puntos
        qs('#hotspots').style.visibility = ''
        buttons.forEach((b) => b.classList.remove('on'))
        focusOn(null)
        if (config.closeInfo) config.closeInfo() // presentacion propia (p. ej. el rastreo): se quita
        if (config.onPick) config.onPick(-1)
        updateCount()
    }
    // Marca un punto como visto (al dejar de mirarlo).
    // onSeen puede devolver los milisegundos que dura su animacion (p. ej. guardar el objeto):
    // la tarjeta se oculta y el flujo continua cuando termina.
    const markSeen = (i) => {
        if (!config.autoNext || seen.has(i)) return 0
        seen.add(i)
        return (config.onSeen && config.onSeen(i)) || 0
    }
    const afterSeen = (wait, fn) => {
        if (!wait) return fn()
        state.tipState = null
        tip.hidden = true
        setTimeout(() => state.cur === stepName && fn(), wait)
    }
    // Siguiente punto que aun no se ha visto (primero los de adelante, luego los anteriores); -1 si ya no queda ninguno
    const nextUnseen = (from) => {
        for (let step = 1; step < total; step++) {
            const j = (from + step) % total
            if (!seen.has(j) && !buttons[j].hidden) return j
        }
        return -1
    }
    const open = (i) => {
        const item = config.items[i]
        const reread = opened.has(i) // si se vuelve a una nota que ya se leyo (con Regresar), lleva un check verde
        opened.add(i)
        buttons.forEach((b, k) => b.classList.toggle('on', i === k))
        buttons[i].classList.add('seen')
        if (config.onPick) config.onPick(i)
        focusOn(item.focus || item.anchor, item.zoom || config.zoom, item.rot) // focus = el centro del objeto, si el paso lo calcula
        panel.hidden = true
        qs('#hotspots').style.visibility = 'hidden'
        if (config.renderInfo) {
            // presentacion propia en lugar de la tarjeta de texto: config.renderInfo(i, item, volver)
            config.renderInfo(i, item, () => afterSeen(markSeen(i), showAll))
            audio.ding()
            updateCount()
            return
        }
        // sequential: el boton lleva directo al siguiente punto que falta por ver (y dice "Listo" en el ultimo)
        const label = config.sequential
            ? nextUnseen(i) >= 0
                ? config.nextLabel || 'Siguiente'
                : config.lastLabel || 'Listo'
            : config.backLabel || 'Ver otros'
        tip.innerHTML =
            '<div class="num">' +
            (item.num || i + 1 + ' de ' + total) +
            '</div>' +
            '<div class="ttl"><span class="ico">' +
            icon(item.icon) +
            '</span><h3>' +
            item.title +
            '</h3></div>' +
            '<p>' +
            item.text +
            '</p>' +
            (config.stepper
                ? // por pasos: Regresar (desde el segundo) y Continuar; en el ultimo, Listo en naranja
                  '<div class="row">' +
                  (i > 0 ? '<button class="btn ghost" data-a="prev">' + (config.prevLabel || 'Regresar') + '</button>' : '') +
                  '<button class="btn' +
                  (i === total - 1 ? ' coral' : '') +
                  '" data-a="step">' +
                  (i === total - 1 ? config.lastLabel || 'Listo' : config.nextLabel || 'Continuar') +
                  '</button></div>' +
                  (config.hint ? '<p class="hintline"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12a8 8 0 0 1 14-5.3M20 12a8 8 0 0 1-14 5.3M18 3v4h-4M6 21v-4h4"/></svg>' + config.hint + '</p>' : '')
                : // un solo boton: volver a la vista general para escoger otro
                  '<div class="row"><button class="btn" data-a="all">' + label + '</button></div>')
        tip.hidden = false
        state.tipState = { anchor: item.anchor, fixed: !!config.fixedTip }
        // la tarjeta aparece (y cambia de un punto al siguiente) con un fundido suave
        tip.classList.toggle('read', reread)
        tip.classList.remove('swap')
        void tip.offsetWidth
        tip.classList.add('swap')
        config.onOpen?.(i, item) // el paso puede mostrar algo mas junto a la tarjeta (p. ej. la pieza en 3D del rastreo)
        if (config.stepper) {
            qs('[data-a=prev]', tip)?.addEventListener('click', () => {
                audio.blip()
                open(i - 1)
            })
            qs('[data-a=step]', tip).addEventListener('click', () => {
                audio.blip()
                if (i < total - 1) open(i + 1)
                else config.finish()
            })
        } else {
            qs('[data-a=all]', tip).addEventListener('click', () => {
                audio.blip()
                afterSeen(markSeen(i), () => {
                    const next = config.sequential ? nextUnseen(i) : -1
                    if (next >= 0) open(next)
                    else showAll()
                })
            })
        }
        audio.ding()
        updateCount()
    }
    if (config.onlyContinue && !config.autoNext) panel.hidden = true // aparece cuando ya se vieron todos los puntos
    config.items.forEach((item, i) => {
        const button = addHotspot({ anchor: item.anchor, aria: item.title, onClick: () => open(i) })
        if (config.noDots) button.classList.add('off') // sin botones para escoger: los puntos se presentan en orden
        buttons.push(button)
    })
    updateCount()
    if (config.openFirst) setTimeout(() => state.cur === stepName && open(0), config.openDelay ?? 900)
    return { buttons, seen, opened, panel, open }
}
export function showCenterPanel(text, label, onNext, extraClass) {
    showPanel({
        text: text,
        cls: 'center' + (extraClass || ''),
        actions: [
            {
                label: label || 'Continuar',
                fn: onNext,
            },
        ],
    })
}
