/**
 * PANELES: tarjeta principal (#panel), pantallas dinamicas (#dyn) y limpieza al cambiar de paso.
 */
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { createEl, isTouch, qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { showCam } from '../systems/camera.js'
import { setBeacon, setInteract } from '../systems/interaction.js'
import { fearBubbles } from '../three/characters.js'
import { clearHotspots } from './hotspots.js'
import { hideMoveHint, hideStopLabel, setObjective, showScrollHint } from './hud.js'
import { stopTour } from '../systems/scrollTour.js'

export function showPanel(opts) {
    let t = qs('#panel')
    t.className = 'card ' + (opts.cls || '')
    t.hidden = false
    t.innerHTML =
        (opts.title ? '<h2>' + opts.title + '</h2>' : '') +
        (opts.text ? '<p>' + opts.text + '</p>' : '') +
        (opts.html || '') +
        (opts.actions && opts.actions.length ? '<div class="actions"></div>' : '')
    let a = qs('.actions', t)
    ;(opts.actions || []).forEach((o) => {
        let s = createEl('button', 'btn' + (o.ghost ? ' ghost' : '') + (o.cls ? ' ' + o.cls : ''))
        s.textContent = o.label
        s.disabled = !!o.disabled
        s.addEventListener('click', () => {
            audio.blip()
            o.fn()
        })
        a.appendChild(s)
        o.el = s
    })
    return t
}
export function showDynamic(html) {
    let t = qs('#dyn')
    t.innerHTML = html
    t.classList.add('active')
    return t
}
export function setControlsHint(kind) {
    let t = qs('#hint')
    if (!kind || isTouch) {
        t.hidden = true
        return
    }
    const text = content.controls
    t.innerHTML =
        '<b class="htitle">' +
        text.title +
        '</b>' +
        (kind === 'fp'
            ? '<span><kbd>←</kbd><kbd>→</kbd> girar la vista</span>'
            : '<span class="arrows"><kbd>↑</kbd><kbd>←</kbd><kbd>↓</kbd><kbd>→</kbd></span><span class="hl">' +
              text.move +
              '</span>')
    t.hidden = false
}
export function resetScreen() {
    qs('#panel').hidden = true
    qs('#dyn').classList.remove('active')
    qs('#dyn').innerHTML = ''
    qs('#home').classList.remove('active')
    qs('#callouts').hidden = true
    qs('#callouts').className = ''
    qs('#callouts').innerHTML = ''
    qs('#tip').hidden = true
    state.tipState = null
    showCam.follow = null
    qs('#hotspots').style.visibility = ''
    qs('#timer').hidden = true
    clearHotspots()
    setObjective(null)
    setBeacon(null)
    setInteract(null)
    setControlsHint(null)
    stopTour()
    showScrollHint(false)
    hideStopLabel()
    qs('#prompt').hidden = true
    qs('#stick').hidden = true
    qs('#quakeBanner').hidden = true
    qs('#blackout').classList.remove('on', 'full')
    hideMoveHint()
    fearBubbles.forEach((e) => (e.visible = false))
}
