/**
 * PASOS de la etapa DURANTE (parte 2): tamanos de mascotas.
 * Todo ocurre en la misma habitacion de las tres experiencias (misma luz y fondo), con el temblor mas suave.
 * Orden: explicacion (tarjeta casi transparente) -> la camara se acerca a la puerta, donde esperan Cacao y Nube ->
 * se escoge el perro o el gato -> (perro) se escoge su tamano y se pulsa Continuar -> se ve el cambio de tamano y la
 * informacion, con la mascota en el centro -> al verlo todo, el usuario llega por un lado, abre la puerta, sale con
 * sus mascotas y la puerta se cierra antes del fundido hacia la siguiente etapa.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { QUAKE } from '../config.js'
import { session, state } from '../core/state.js'
import { damp, isCompact, qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { goTo, steps, transitionTo } from './navigation.js'
import { startInfoTour } from './helpers.js'
import { setCameraMode, setOrbit } from '../systems/camera.js'
import { quake, startQuake } from '../systems/quake.js'
import { cat, dog, person, placePet, setPetMood, walkPath } from '../three/characters.js'
import { place, roundedBox } from '../three/helpers.js'
import { trackPetGlow } from '../three/petGlow.js'
import { createCarryDemo } from '../systems/carryDemo.js'
import { createPawDemo, openPawEditor } from '../systems/pawDemo.js'
import { createAccessory } from '../three/models/accessories.js'
import { createHarness } from '../three/models/harness.js'
import { DOOR, LAYOUT, setThirdDoor } from '../three/thirdRoom.js'
import { canvas, mainScene } from '../three/renderer.js'
import { world } from '../three/world.js'
import { addHotspot } from '../ui/hotspots.js'
import { fadeStopLabel, hideStopLabel, showStopLabel } from '../ui/hud.js'
import { showPanel } from '../ui/panels.js'
import { resetPerson } from './sofaScene.js'

const SOFT_SHAKE = 0 // el temblor de la camara en esta parte (1 = el de las experiencias): 0 porque en estos pasos hay que leer

// ---- Camara (orbita alrededor de un punto): vista de toda la habitacion y vistas de la puerta ----
const hubView = () => ({
    theta: 0.8,
    r: 13.5,
    h: 8.4,
    tx: 0,
    ty: 0.9,
    tz: 0,
    sx: 0,
    sy: innerWidth > 720 ? 2.1 : 3,
    amp: 0.12,
})
const roomCentered = () => ({ ...hubView(), sy: 0 }) // la habitacion en el centro de la pantalla
const AT_DOOR = { theta: 0, r: 4.2, h: 1.9, tx: -2.0, ty: 0.8, tz: -0.07, sx: 0, sy: 0.15, amp: 0 }
const sizeCam = hubView() // valores actuales: se acercan poco a poco a la meta
let camGoal = hubView()
function driveCamera(dt) {
    Object.keys(camGoal).forEach((key) => (sizeCam[key] = damp(sizeCam[key], camGoal[key], 2.2, dt)))
    setOrbit({ ...sizeCam, speed: 0.09 })
}

// ---- Mascotas junto a la puerta (pared izquierda de la habitacion, ver thirdRoom.js) ----
const DOG_AT = LAYOUT.atDoor.dog
const CAT_AT = LAYOUT.atDoor.cat
const DOG_SCALE = { pick: 0.65, large: 0.82, small: 0.45 } // se nota la diferencia, sin exagerar
const CAT_SCALE = 0.6
const FACING = Math.PI / 2 - 0.15 // casi de frente a la camara (que mira hacia -x): te miran a ti
function placeAtDoor(dogScale = DOG_SCALE.pick) {
    placePet(dog, DOG_AT.x, 0, DOG_AT.z, FACING, dogScale)
    placePet(cat, CAT_AT.x, 0, CAT_AT.z, FACING, CAT_SCALE)
    dog.visible = cat.visible = true
    setPetMood(dog, { wag: 1.2, eyes: 1.05 })
    setPetMood(cat, { wag: 1.1, eyes: 1.05 })
}

/**
 * Puerta de salida: la puerta de la habitacion (static/habitacion.glb) con su animacion, y un fondo oscuro detras del
 * hueco. La hoja se abre y se cierra con setThirdDoor(k) (0 cerrada, 1 abierta).
 */
let exit = null
function exitDoor() {
    if (exit) return exit
    // el hueco de la puerta da a un lugar oscuro: un fondo grande detras
    const dark = place(roundedBox(0.2, 2.7, 2.6, 0.01, '#050d1f'), DOOR.x - 1.1, 1.3, DOOR.z)
    dark.visible = false
    world.root.add(dark) // dentro de la casa: tiembla con ella
    exit = { dark }
    return exit
}

/** El sismo sigue con el mismo ambiente de las tres experiencias (luz, polvo y fondo de noche), pero sin sacudir la camara. */
function softQuake() {
    if (!quake.active) startQuake()
    quake.shakeTarget = SOFT_SHAKE
    quake.target = QUAKE.intensity
    audio.duck(0.75) // la musica de esta parte se oye mejor
}

/** Entra al paso: camara orbital, temblor suave, la puerta propia cerrada y la camara hacia su meta. */
function setUpRoom(goal) {
    setCameraMode('orbit')
    state.bgOverride = 'night' // el mismo fondo oscuro de las tres experiencias
    person.visible = false
    const door = exitDoor()
    door.dark.visible = true
    setThirdDoor(0)
    softQuake()
    camGoal = goal
    state.curTick = driveCamera
    state.curExit = () => {
        tempAnchors.splice(0).forEach((anchor) => anchor.removeFromParent())
        door.dark.visible = false
        setThirdDoor(0)
        dog.visible = cat.visible = true
        resetPerson()
    }
}
const ease = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}
const lerp = (a, b, k) => a + (b - a) * k

steps.sizeIntro = {
    stage: 2,
    w: 0.85,
    prev: 'hub',
    next: 'sizePick',
    enter() {
        Object.assign(sizeCam, hubView())
        setUpRoom(roomCentered()) // la habitacion baja al centro de la pantalla
        placeAtDoor()
        sizeTextSeen = false
        // la misma tarjeta oscura del inicio del "Durante" (linea, etiqueta, titulo y texto que aparece palabra por palabra)
        const intro = content.sizeIntro
        const words = intro.text
            .split(' ')
            .map((w, i) => '<span style="--i:' + i + '">' + w + '</span>')
            .join(' ')
        const panel = showPanel({
            cls: 'center quakecard',
            html:
                '<svg class="qline" viewBox="0 0 400 40" preserveAspectRatio="none" aria-hidden="true"><path pathLength="1" d="M0 20H120l8-4 8 8 8-16 8 28 8-34 8 30 8-22 8 14 8-6 8 4H400"/></svg>' +
                '<span class="qkick">' +
                intro.kick +
                '</span><h2 class="qtitle">' +
                intro.title +
                '</h2><p class="qtext">' +
                words +
                '</p>',
            actions: [
                {
                    label: intro.cta,
                    cls: 'danger',
                    fn: () => {
                        panel.classList.add('leaving')
                        setTimeout(() => state.cur === 'sizeIntro' && goTo('sizePick'), 450)
                    },
                },
            ],
        })
    },
}

/** Cacao y Nube nerviosos: miran de un lado a otro, se mueven un poco sin rumbo y tiemblan apenas. Devuelve la funcion de cada cuadro. */
function nervousPets() {
    setPetMood(dog, { wag: 0.2, shiver: 0.6, eyes: 1.3 })
    setPetMood(cat, { wag: 0.2, shiver: 0.6, eyes: 1.3 })
    const walkers = [dog, cat].map((pet, i) => ({
        pet,
        look: 0.6 + i * 0.8,
        move: 3 + i * 1.8,
        home: { x: pet.userData.base.x, z: pet.userData.base.z },
    }))
    return (dt) =>
        walkers.forEach((w) => {
            const a = w.pet.userData
            w.look -= dt
            if (w.look <= 0 && !a.walking) {
                w.look = 1.3 + Math.random() * 1.8
                a.faceTo = FACING + (Math.random() * 2 - 1) * 0.6 // gira de golpe hacia un lado, como buscando algo
            }
            w.move -= dt
            if (w.move <= 0 && !a.walking) {
                w.move = 4 + Math.random() * 3
                // un pasito muy corto y se queda mirando a otro lado (siempre junto a su lugar)
                walkPath(
                    w.pet,
                    [
                        {
                            x: w.home.x + (Math.random() * 2 - 1) * 0.06,
                            z: w.home.z + (Math.random() * 2 - 1) * 0.06,
                            ry: FACING + (Math.random() * 2 - 1) * 0.6,
                        },
                    ],
                    0.3,
                )
            }
        })
}

const tempAnchors = []
/** Cacao y Nube juntas en la puerta, nerviosas. Devuelve la funcion de cada cuadro; al salir del paso se quita la indicacion de arriba. */
function setUpCast() {
    const nervous = nervousPets()
    const leave = state.curExit
    state.curExit = () => {
        hideStopLabel()
        if (leave) leave()
    }
    return nervous
}
/** Un punto fijo (que no sigue a la mascota) a la altura de su cabeza, para colgar un boton junto a ella. */
function fixedHeadAnchor(pet) {
    pet.updateMatrixWorld(true)
    const anchor = new THREE.Object3D()
    pet.userData.anchors.head.getWorldPosition(anchor.position)
    mainScene.add(anchor) // (la casa tiembla; esto no)
    tempAnchors.push(anchor)
    return anchor
}

// Vista de la eleccion: mas cerca, con Cacao y Nube entre el texto de arriba y el boton de abajo
const PICK_VIEW = { theta: 0, r: 3.1, h: 1.5, tx: -2.0, ty: 0.55, tz: -0.05, sx: 0, sy: 0.1, amp: 0 }
// una mascota ya esta vista cuando se leyeron todos sus tamanos (el perro: grande y mediano)
const petDone = (which) => (which === 'cat' ? session.sizes.has('cat') : session.sizes.has('large') && session.sizes.has('small'))
let sizeTextSeen = false // la explicacion de esta pantalla solo sale la primera vez (al volver de ver un tamano se va directo a escoger)
steps.sizePick = {
    stage: 2,
    w: 0.92,
    prev: 'sizeIntro',
    next: 'despIntro',
    enter() {
        setUpRoom({ ...PICK_VIEW }) // la camara se acerca a las dos mascotas, que quedan entre el texto de arriba y el boton de abajo
        placeAtDoor()
        const nervous = setUpCast() // Cacao y Nube nerviosas
        const timers = []
        const leave = state.curExit
        state.curExit = () => {
            timers.forEach(clearTimeout)
            if (leave) leave()
        }
        state.curTick = (dt) => {
            driveCamera(dt)
            nervous(dt)
        }
        const text = content.sizePick
        const showChoices = () => {
            // la mascota se escoge con el circulo amarillo (sin texto): los circulos quedan fijos y la que ya se vio lleva un check verde
            const pending = [dog, cat].filter((pet) => !petDone(pet === cat ? 'cat' : 'dog'))
            showStopLabel(text.title, pending.length ? text.sub : text.done, true)
            showPanel({ cls: 'only', actions: [{ label: 'Continuar', fn: () => goTo('sizeOut') }] })
            ;[dog, cat].forEach((pet, i) => {
                const which = pet === cat ? 'cat' : 'dog'
                const anchor = fixedHeadAnchor(pet)
                anchor.position.y *= 0.6 // el circulo queda sobre el cuerpo de la mascota, no sobre la cabeza
                const circle = addHotspot({
                    cls: 'dot ghost glow',
                    aria: which === 'cat' ? 'Ver tamaños del gato' : 'Ver tamaños del perro',
                    anchor,
                    onClick: () => goTo('sizeInfo', { pet: which }),
                })
                circle.style.setProperty('--pd', i * 0.25 + 's')
                circle.classList.add('pop', 'wide')
                circle.classList.toggle('seen', petDone(which))
                trackPetGlow(pet, circle, { seen: () => petDone(which) }) // la silueta brilla dorada (verde si ya se vio)
            })
        }
        qs('#panel').hidden = true
        if (sizeTextSeen) return showChoices()
        // primero un texto mas descriptivo, mientras las mascotas se ven nerviosas; despues el texto se desvanece y aparecen las opciones
        sizeTextSeen = true
        showStopLabel(text.pre.t, text.pre.s, true)
        timers.push(setTimeout(() => fadeStopLabel(900), 6500))
        timers.push(setTimeout(() => state.cur === 'sizePick' && showChoices(), 7600))
    },
}

const NOTE_ICONS = { neck: 'shield', back: 'hand', paws: 'paw', rear: 'kit' } // un icono por cada nota
/**
 * La mascota escogida: sus notas se ven una por una (la misma dinamica del kit: tarjeta a la derecha con Regresar y Continuar,
 * y Listo en la ultima). El perro pasa primero por el tamano grande y despues por el mediano, y su tamano cambia a la vista.
 */
steps.sizeInfo = {
    stage: 2,
    w: 0.97,
    prev: 'sizePick', // desde aqui se vuelve a escoger la mascota
    next: 'despIntro',
    enter(e) {
        const isCat = e.pet === 'cat'
        const keys = isCat ? ['cat'] : [e.key]
        const pet = isCat ? cat : dog
        const at = isCat ? CAT_AT : DOG_AT
        // la camara se acerca mas: la mascota queda a la izquierda y la tarjeta a la derecha
        setUpRoom({ ...AT_DOOR, r: 3.0, h: 1.3, tx: at.x - 0.1, ty: 0.5, tz: at.z, sx: isCompact() ? 0 : -0.58, sy: 0 })
        placeAtDoor()
        const nervous = setUpCast()
        const head = fixedHeadAnchor(pet)
        // arnes y correa (static/arnes.glb): no se ven hasta tocar "Ver como se pone" en la primera nota
        const harness = createHarness(pet, isCat ? 'cat' : keys[0] === 'small' ? 'dogSmall' : 'dogLarge')
        // como cargar al perro (solo los perros): el perro toma la pose de cargado y la persona que lo levanta es un dibujo; se ve al tocar la nota
        const carry = createCarryDemo({ dog: pet, kind: isCat ? 'cat' : keys[0], home: at })
        // las notas de cargar a la mascota (en el perro la segunda; en el gato la tercera, que reemplaza a la de no sacarlo a la fuerza)
        const CARRY_NOTES = ['Cárgalos con los dos brazos', 'Cárgalo con apoyo', 'Cárgalo pegado a tu pecho']
        const cameraBefore = { r: camGoal.r, h: camGoal.h, sx: camGoal.sx, tx: camGoal.tx, ty: camGoal.ty, tz: camGoal.tz, theta: camGoal.theta }
        // la nota de las patas: la mascota levanta una pata y la camara se acerca a la almohadilla
        const paw = createPawDemo({ pet, kind: isCat ? 'cat' : 'dog' })
        let closePawEditor = null // editor en pantalla de la pata (solo al desarrollar): ver systems/pawDemo.js
                // camilla (perro mediano / grande) o transportadora (perro pequeno y gato): la mascota se sube o entra, igual que el gato de muestra del modelo
        const accKind = !isCat && keys[0] === 'large' ? 'camilla' : 'transportadora'
        const accScale = accKind === 'camilla' ? 1.6 : isCat ? 1.15 : 1.35 // tamano del accesorio respecto al gato de muestra del modelo (segun lo que mide la mascota)
        const accessory = createAccessory({ pet, kind: accKind, home: at, stage: { x: -0.8, z: -0.45 }, scale: accScale }) // (se muestra en el piso libre del centro del cuarto)
        const otherPet = isCat ? dog : cat
        let dragBefore = null // el arrastre para girar la camara, que se quita mientras se ve como cargar al perro (el dibujo es de frente)
        // arrastrar con el puntero gira la camara alrededor de la mascota (con limites: del otro lado esta la pared de la puerta);
        // un aviso abajo a la izquierda lo indica y se va en cuanto se arrastra
        const hint = document.createElement('div')
        hint.id = 'orbitHint'
        hint.innerHTML =
            '<svg viewBox="0 0 64 28" aria-hidden="true"><path d="M4 14h56M4 14l9-8M4 14l9 8M60 14l-9-8M60 14l-9 8"/></svg><span>Arrastra para girar alrededor</span>'
        document.body.appendChild(hint)
        canvas.style.cursor = 'grab'
        state.onDragStart = () => (canvas.style.cursor = 'grabbing')
        state.onDragEnd = () => (canvas.style.cursor = 'grab')
        state.onDrag = (dx, dy) => {
            camGoal.theta = Math.min(1.45, Math.max(-0.6, camGoal.theta - dx * 0.006))
            camGoal.h = Math.min(3, Math.max(0.55, camGoal.h + dy * 0.008)) // un poco arriba o abajo
            hint.classList.add('gone')
        }
        // el fondo se desenfoca mientras se ve cada mascota (queda nitida solo ella)
        const blur = document.createElement('div')
        blur.className = 'focusBlur pet'
        document.body.appendChild(blur)
        setTimeout(() => blur.classList.add('on'), 30)
        const leave = state.curExit
        state.curExit = () => {
            blur.remove()
            qs('#stopLabel').classList.remove('sizeLbl')
            hint.remove()
            canvas.style.cursor = ''
            state.onDrag = state.onDragStart = state.onDragEnd = null
            harness?.dispose()
            carry?.dispose()
            paw.dispose()
            closePawEditor?.()
            accessory?.dispose()
            otherPet.visible = true
            qs('#tip').classList.remove('bright')
            if (leave) leave()
        }
        let dogScale = DOG_SCALE.pick
        let dogGoal = DOG_SCALE.pick
        state.curTick = (dt) => {
            driveCamera(dt)
            if (!carry?.active && !paw.active && !accessory?.active) nervous(dt) // (mientras lo cargan, muestra la pata o usa el accesorio, la mascota no se mueve por su cuenta)
            accessory?.update(dt)
            paw.update(dt)
            if (paw.active && paw.k > 0.05) {
                // la camara sigue a la pata levantada
                camGoal.tx = paw.target.x
                camGoal.ty = paw.target.y
                camGoal.tz = paw.target.z
            }
            carry?.update(dt)
            harness?.update(dt)
            if (!isCat) {
                // el perro pasa de su tamano normal al grande o al pequeno, para que se vea la diferencia
                dogScale = damp(dogScale, dogGoal, 3, dt)
                dog.scale.set(dogScale, dogScale, dogScale)
            }
        }
        // el perro: primero se escoge que tamano ver (grande o mediano); despues se ven sus notas
        if (!isCat && !e.key) {
            const text = content.sizePick
            showStopLabel(text.dogTitle, text.dogSub, 'right')
            showPanel({ cls: 'only', actions: [{ label: 'Ver otra mascota', fn: () => goTo('sizePick') }] })
            ;['large', 'small'].forEach((key, i) => {
                const pill = addHotspot({
                    cls: 'pill',
                    label: content.sizes[key].name,
                    anchor: head, // fijo: no sigue a la mascota
                    onClick: () => goTo('sizeInfo', { pet: 'dog', key }),
                })
                pill.style.marginLeft = '250px'
                pill.style.marginTop = (i ? 34 : -34) + 'px'
                pill.style.setProperty('--pd', i * 0.25 + 's')
                pill.classList.add('pop')
                pill.classList.toggle('seen', session.sizes.has(key))
            })
            return
        }
        const items = keys.flatMap((key) =>
            content.sizes[key].items.map((note, i, all) => ({
                anchor: head,
                key,
                title: note.t,
                text: note.d,
                icon: NOTE_ICONS[note.a],
                num: i + 1 + ' de ' + all.length,
            })),
        )
        let currentKey = null
        startInfoTour({
            onlyContinue: true, // el panel de abajo no se usa: la ultima nota trae su boton Listo
            stepper: true,
            noDots: true,
            fixedTip: true, // la tarjeta va fija a la derecha, igual que en el kit
            prevLabel: 'Regresar',
            nextLabel: 'Continuar',
            lastLabel: 'Listo',
            openFirst: true,
            openDelay: 700,
            items,
            // al terminar: el gato vuelve a la eleccion de mascota; el perro, a la eleccion de tamaño si falta el otro
            finish: () => (isCat || petDone('dog') ? goTo('sizePick') : goTo('sizeInfo', { pet: 'dog' })),
            onOpen(i, item) {
                qs('#tip').classList.add('bright') // tarjeta clara y alegre
                qs('#tip').style.translate = '' // (la tarjeta vuelve a su lugar si se movio para dejar ver al perro cargado)
                blur.classList.remove('carry')
                harness?.reset() // al cambiar de nota el arnes se quita y la mascota vuelve a estar como antes (con su collar)
                // la nota de las patas (la tercera): levanta una pata y la camara enfoca la almohadilla; al salir de la nota todo vuelve a su lugar
                if (item.title === 'Cuida sus patas') {
                    const size = isCat ? 1 : DOG_SCALE[item.key] / DOG_SCALE.large // (el perro pequeno es mas chico: la camara se acerca mas)
                    camGoal.r = isCat ? 0.5 : 0.62 * size // muy cerca: la almohadilla llena el cuadro
                    camGoal.h = isCat ? 0.45 : 0.5 * size
                    camGoal.sx = -0.12
                    camGoal.theta = 0
                    paw.play()
                    if (!isCat && !closePawEditor) closePawEditor = openPawEditor()
                } else if (paw.active) {
                    paw.dispose()
                    closePawEditor?.()
                    closePawEditor = null
                    Object.assign(camGoal, cameraBefore)
                }
                // la camilla (nota del traslado del perro grande) o la transportadora: la mascota se sube o entra; al pasar a otra nota todo vuelve a su lugar
                const isAcc = item.title === 'Planea el traslado' || item.title === 'Transportadora' || item.title === 'Transportadora rígida'
                if (accessory?.active && !isAcc) {
                    accessory.dispose(true)
                    otherPet.visible = true
                    Object.assign(camGoal, cameraBefore)
                }
                if (accessory && isAcc) {
                    const tip = qs('#tip')
                    const button = document.createElement('button')
                    button.type = 'button'
                    button.className = 'btn ghost harnessBtn'
                    button.textContent = accKind === 'camilla' ? 'Toca para ver cómo se usa la camilla' : 'Toca para ver cómo entra'
                    button.addEventListener('click', () => {
                        audio.blip()
                        otherPet.visible = false // la otra mascota se oculta: no estorba en la vista
                        // la camara se aleja y mira al centro del cuarto, entre la mascota y el accesorio (que queda a la izquierda)
                        camGoal.r = accKind === 'camilla' ? 4.6 : 4.1
                        camGoal.h = accKind === 'camilla' ? 2.3 : 2
                        camGoal.tx = -0.8
                        camGoal.ty = 0.45
                        camGoal.tz = accKind === 'camilla' ? 0.55 : 0.3
                        camGoal.sx = -0.35
                        camGoal.theta = cameraBefore.theta
                        accessory.play()
                    })
                    qs('p', tip).after(button)
                }
                const isCarry = CARRY_NOTES.includes(item.title)
                if (carry?.active && !isCarry) {
                    carry.dispose(true) // al pasar a otra nota el perro vuelve a su lugar, los dibujos se quitan y la camara tambien
                    Object.assign(camGoal, cameraBefore)
                    if (dragBefore) {
                        state.onDrag = dragBefore // se vuelve a poder girar la camara
                        canvas.style.cursor = 'grab'
                        dragBefore = null
                    }
                }
                // la primera nota es la del arnes: un boton aparte muestra como se pone (y se puede volver a ver)
                if (harness && i === 0) {
                    const tip = qs('#tip')
                    const button = document.createElement('button')
                    button.type = 'button'
                    button.className = 'btn ghost harnessBtn'
                    button.textContent = 'Toca para ver cómo se pone'
                    button.addEventListener('click', () => {
                        audio.blip()
                        harness.play()
                    })
                    qs('p', tip).after(button)
                }
                // la nota de cargar al perro (la segunda): un boton aparte muestra como se levanta (y se puede volver a ver)
                if (carry && isCarry) {
                    const tip = qs('#tip')
                    const button = document.createElement('button')
                    button.type = 'button'
                    button.className = 'btn ghost harnessBtn'
                    button.textContent = 'Toca para ver cómo se carga'
                    button.addEventListener('click', () => {
                        audio.blip()
                        // la camara se aleja un poco y sube la mirada para que se vean el perro y el dibujo de la persona
                        camGoal.r = cameraBefore.r * 1.3
                        camGoal.h = cameraBefore.h * 1.1
                        camGoal.sx = cameraBefore.sx * 0.4
                        camGoal.ty = cameraBefore.ty + 0.45
                        camGoal.theta = cameraBefore.theta // de frente: en esta parte la camara no se gira
                        if (!dragBefore) dragBefore = state.onDrag
                        state.onDrag = null
                        canvas.style.cursor = ''
                        hint.classList.add('gone')
                        qs('#tip').style.translate = '90px 0' // la tarjeta se corre a la derecha: no tapa al perro ni al dibujo
                        blur.classList.add('carry') // lo nitido es el perro y el dibujo
                        carry.play()
                    })
                    qs('p', tip).after(button)
                }
                // (si se acaba de ver el ultimo tamano, ya queda marcado antes de volver)
                // titulo arriba sobre la tarjeta: al cambiar de tamano (grande -> mediano) cambia el titulo y la mascota
                if (item.key !== currentKey) {
                    currentKey = item.key
                    const info = content.sizes[item.key]
                    showStopLabel(info.name, info.weight, 'right')
                    qs('#stopLabel').classList.add('sizeLbl') // titulo de una sola linea, aunque el nombre sea largo
                    if (!isCat) dogGoal = DOG_SCALE[item.key]
                }
                // al llegar a la ultima nota de ese tamano ya se vio completo (check verde en la eleccion)
                if (items[i + 1]?.key !== item.key) session.sizes.add(item.key)
            },
        })
    },
}

/** Final de los tamanos: el usuario llega por un lado, abre la puerta, sale con sus mascotas y la cierra. */
steps.sizeOut = {
    stage: 2,
    w: 0.99,
    prev: 'sizePick',
    next: 'despIntro',
    enter() {
        setUpRoom({ ...AT_DOOR })
        placeAtDoor()
        exitDoor()
        const limbs = person.userData
        // el usuario entra por el lado (z grande, fuera de la pantalla) y se para frente a la puerta
        const SIDE = { x: -1.55, z: 3.9 }
        const FRONT = { x: -1.5, z: DOOR.z }
        const WALK_IN = 2.5 // segundos
        const T_OPEN = 3.4 // empieza a abrir la puerta
        const OPEN_TIME = 1.4
        const T_OUT = T_OPEN + OPEN_TIME + 0.2 // salen las mascotas y el usuario
        const OUT_TIME = 2.2
        const T_CLOSE = T_OUT + OUT_TIME + 0.3
        const CLOSE_TIME = 1.2
        const T_END = T_CLOSE + CLOSE_TIME + 0.3
        person.scale.set(1, 1, 1)
        person.visible = true
        person.position.set(SIDE.x, 0, SIDE.z)
        person.rotation.y = Math.PI
        let time = 0
        let openSound = false
        let petsOut = false // Nube ya salio
        let dogOut = false // Cacao ya salio
        let closeSound = false
        let leaving = false
        state.curTick = (dt) => {
            driveCamera(dt)
            time += dt
            // llega caminando y se vuelve hacia la puerta
            if (time < WALK_IN) {
                const w = ease(time / WALK_IN)
                person.position.set(lerp(SIDE.x, FRONT.x, w), 0, lerp(SIDE.z, FRONT.z, w))
                limbs.walking = true
                const swing = Math.sin(time * 9) * 0.65
                limbs.legL.rotation.x = swing
                limbs.legR.rotation.x = -swing
                limbs.armL.rotation.x = -swing * 0.8
                limbs.armR.rotation.x = swing * 0.8
            } else if (time < T_OUT) {
                limbs.walking = false
                limbs.legL.rotation.x = limbs.legR.rotation.x = 0
                limbs.armL.rotation.x = 0
                person.rotation.y = lerp(Math.PI, Math.PI * 1.5, ease((time - WALK_IN) / 0.6)) // mira a la puerta (-x)
                limbs.armR.rotation.x = lerp(0, -1.3, ease((time - T_OPEN + 0.5) / 0.5)) // estira la mano
                limbs.armRaise = ease((time - T_OPEN + 0.5) / 0.5)
            }
            // abre la puerta (gira hacia afuera)
            if (time > T_OPEN && time < T_CLOSE) {
                if (!openSound) {
                    openSound = true
                    audio.creak()
                }
                setThirdDoor(ease((time - T_OPEN) / OPEN_TIME))
            }
            // salen Nube (mas independiente, primero), Cacao un momento despues y el usuario con ellos
            if (time > T_OUT && !petsOut) {
                petsOut = true
                setPetMood(cat, { wag: 2.4, eyes: 1.1 })
                walkPath(cat, [{ x: DOOR.x - 0.3, z: DOOR.z + 0.2 }, { x: DOOR.x - 2, z: DOOR.z + 0.2, ry: -Math.PI / 2 }], 1.3)
            }
            if (time > T_OUT + 0.7 && !dogOut) {
                dogOut = true
                setPetMood(dog, { wag: 2.6, eyes: 1.1 })
                walkPath(dog, [{ x: DOOR.x - 0.3, z: DOOR.z - 0.2 }, { x: DOOR.x - 2, z: DOOR.z - 0.2, ry: -Math.PI / 2 }], 1.5)
                audio.bark()
            }
            if (time > T_OUT && time < T_CLOSE) {
                const w = ease((time - T_OUT) / OUT_TIME)
                person.position.set(lerp(FRONT.x, DOOR.x - 1.7, w), 0, DOOR.z)
                person.rotation.y = -Math.PI / 2
                limbs.walking = w > 0 && w < 1
                limbs.armRaise = 1 - ease(w * 3)
                const swing = w > 0 && w < 1 ? Math.sin(time * 9) * 0.65 : 0
                limbs.legL.rotation.x = swing
                limbs.legR.rotation.x = -swing
                limbs.armL.rotation.x = -swing * 0.8
                limbs.armR.rotation.x = swing * 0.8
            }
            // al cruzar la pared ya estan afuera: dejan de verse
            if (person.position.x < DOOR.x - 0.2) person.visible = false
            if (dog.position.x < DOOR.x - 0.2) dog.visible = false
            if (cat.position.x < DOOR.x - 0.2) cat.visible = false
            // cierra la puerta
            if (time > T_CLOSE) {
                if (!closeSound) {
                    closeSound = true
                    audio.creak()
                }
                setThirdDoor(1 - ease((time - T_CLOSE) / CLOSE_TIME))
            }
            // y la escena se desvanece, con calma, hacia la siguiente etapa
            if (time > T_END && !leaving) {
                leaving = true
                transitionTo('despIntro', null, 1800)
            }
        }
    },
}
