/**
 * HABITACION DE TERCERA PERSONA: escenario exportado de Blender (static/escenario-luces.glb).
 * Es el cuarto que se ve desde arriba en el sismo, en las tres experiencias y en los tamanos.
 *
 * El .glb viene en una escala mas chica que el resto de la casa (la puerta mide 1.5 m): se agranda ROOM_SCALE veces
 * para que la puerta mida ~2.25 m y las mascotas y el personaje queden bien. Se gira para que la puerta quede en la
 * pared izquierda (x negativo), centrado en el origen y con el piso en y = 0.
 *
 * El .glb no trae colores: se pintan por nombre de objeto (tabla COLORS); el piso lleva tablones de madera. Las dos paredes que dan a la
 * camara y el techo se recortan (clipping) para ver adentro. La puerta y el armario traen su animacion en el .glb.
 *
 * Medidas en el mundo (metros), despues de escalar y girar: ver ROOM. SPOTS lista los muebles y escondites.
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { LIGHT_SCALE } from '../config.js'
import { standardizeMaterials } from './helpers.js'
import { INTERIOR, PLANK_TILE, addMirroredKnob, createCeilingSpot, applyFabric, applyWallDetail, paintPictures, shadedWall, woodMaterial, woodenFurniture } from './interiorLook.js'
import { lampLight, registerExterior, registerInterior } from './renderer.js'
import { world } from './world.js'

// El escenario nuevo (static/escenario-luces.glb) viene a escala real (la puerta mide ~2.07 m): no se agranda
export const ROOM_SCALE = 1
// Si el clip del armario empieza con las hojas cerradas (t = 0) y termina abiertas
const WARDROBE_CLOSED_AT_START = true
const ROT = -Math.PI / 2 // la puerta (en +z del archivo) pasa a la pared izquierda (-x)

export const thirdRoom = {
    root: new THREE.Group(),
    loaded: false,
    mixer: null,
    wardrobeActions: [],
    doorAction: null, // animacion de la hoja de la puerta (puerta1.001 del .glb)
    parts: {}, // nodos por nombre
}
// Medidas del cuarto ya colocado (se calculan al cargar; estos son los valores de reserva)
export const ROOM = { x0: -2.46, x1: 2.46, z0: -2.99, z1: 2.99, h: 2.65 }
// Puerta (centro del hueco en la pared izquierda; se calculan de la malla al cargar)
export const DOOR = { x: -2.46, z: -0.06, w: 0.99, h: 2.07 }

const WALL = INTERIOR.wall // (las paredes llevan ademas un degradado: ver shadedWall)
const FLOOR = INTERIOR.floor
const CEILING = INTERIOR.ceiling
const POT = '#e9dcc0' // ceramica crema
const LEAVES = '#4f7f3f' // verde de hojas
const COLORS = {
    alfombra: '#b7d3c2', // salvia suave: va con la sabana verde azulada y la madera
    asiento: '#6fae9c',
    asiento001: '#6fae9c',
    computador: '#14305e',
    // cuadros: el marco gris y la lamina de color
    cuadro1: INTERIOR.frame,
    cuadro2: INTERIOR.frame,
    cuadro3: INTERIOR.frame,
    imagen: '#9fd0f2',
    imagen001: '#ffd9a0',
    imagen002: '#c9dbff',
    // cama: base de madera, colchon claro, sabana verde azulada y almohadas blancas
    base_madera: INTERIOR.wood,
    colchon: '#eef2f7',
    sabana: '#7cc8b6',
    almohada1: '#ffffff',
    almohada2: '#ffffff',
    // armario: el cuerpo, las dos hojas y la barra de las perchas
    armario: INTERIOR.woodLight,
    puerta1: INTERIOR.wood,
    puerta2: INTERIOR.wood,
    barra: '#b9c3d6',
    // la puerta del cuarto: marco y hoja
    puerta1002: INTERIOR.woodDark,
    puerta1001: INTERIOR.woodDark,
    escritorio: '#c99a68',
    mesa: INTERIOR.woodLight,
    silla: '#4f8f84',
    taza: '#ffffff',
    matera: POT,
    materita: POT,
    hojas: LEAVES,
    hojitas: LEAVES,
}
const materials = {}
const material = (hex, vertexColors = false) =>
    (materials[hex + vertexColors] ||= new THREE.MeshStandardMaterial({
        color: vertexColors ? '#ffffff' : hex,
        vertexColors,
        side: THREE.DoubleSide,
        roughness: 0.82,
        metalness: 0,
    }))

function paintVertices(mesh, pick) {
    const geo = mesh.geometry
    const pos = geo.attributes.position
    const nor = geo.attributes.normal
    const colors = new Float32Array(pos.count * 3)
    const c = new THREE.Color()
    for (let i = 0; i < pos.count; i++) {
        c.set(pick(nor.getY(i), pos.getY(i)))
        colors.set([c.r, c.g, c.b], i * 3)
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    mesh.material = material('#ffffff', true)
}

/** El piso del .glb: tablones de madera con brillo. Las coordenadas de textura se calculan del plano (x, z) para que midan lo mismo en todo el piso. */
function paintFloor(mesh) {
    const pos = mesh.geometry.attributes.position
    const uv = new Float32Array(pos.count * 2)
    const at = new THREE.Vector3()
    mesh.updateMatrix() // (el nodo del piso trae su escala: se usan las medidas del cuarto, no las del nodo)
    for (let i = 0; i < pos.count; i++) {
        at.fromBufferAttribute(pos, i).applyMatrix4(mesh.matrix)
        uv.set([at.x / PLANK_TILE, at.z / PLANK_TILE], i * 2) // tablones de ~0.16 m de ancho
    }
    mesh.geometry.setAttribute('uv', new THREE.BufferAttribute(uv, 2))
    mesh.material = woodMaterial({ side: THREE.DoubleSide })
}

function colorize(top) {
    const meshes = []
    top.traverse((o) => o.isMesh && meshes.push(o))
    meshes.forEach((mesh, i) => {
        mesh.castShadow = top.name !== 'paredes' && top.name !== 'piso' && top.name !== 'alfombra'
        mesh.receiveShadow = true
        if (top.name === 'paredes') {
            // paredes con degradado y techo (el piso es otra malla)
            paintVertices(mesh, (ny, y) => (ny < -0.8 ? CEILING : shadedWall(y * ROOM_SCALE, 2.65)))
        } else if (top.name === 'piso') {
            paintFloor(mesh)
        } else {
            const clothes = ['#ff7a66', '#4a8bdd', '#ffc24d', '#7cc8a0', '#ff8a6f']
            const entry = top.name.startsWith('ropa')
                ? clothes[(parseInt(top.name.slice(4)) || 0) % clothes.length]
                : top.name.startsWith('gancho')
                  ? '#c9d5e8'
                  : COLORS[top.name] || '#c99a68'
            mesh.material = material(Array.isArray(entry) ? entry[Math.min(i, entry.length - 1)] : entry)
        }
    })
}

export async function loadThirdRoom() {
    const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + 'escenario-luces.glb')
    const scene = gltf.scene
    const holder = new THREE.Group() // escala y giro
    holder.scale.setScalar(ROOM_SCALE)
    holder.rotation.y = ROT
    holder.add(scene)
    scene.children.forEach((top) => {
        thirdRoom.parts[top.name] = top
        colorize(top)
    })
    standardizeMaterials(scene) // todo reacciona a las luces
    // la sabana de la cama: con el tejido de tela (conserva su color)
    thirdRoom.parts.sabana?.traverse((o) => {
        if (o.isMesh && o.material && !Array.isArray(o.material)) applyFabric((o.material = o.material.clone()))
    })
    woodenFurniture(scene) // veta de madera en los muebles (cama, armario, escritorio, mesas...)
    paintPictures(scene) // las ilustraciones de los cuadros
    // las paredes del cuarto: pared lisa con grano suave
    thirdRoom.parts.paredes?.traverse((o) => {
        if (o.isMesh && o.material && !Array.isArray(o.material)) applyWallDetail((o.material = o.material.clone()), 'muro-interior.png', 2, 0.2)
    })
    thirdRoom.root.add(holder)
    const leafMeshes = []
    thirdRoom.parts.puerta1001.traverse((o) => o.isMesh && leafMeshes.push(o))
    leafMeshes.forEach(addMirroredKnob) // pomo en las dos caras de la hoja
    // se centra en el origen (x, z) con el piso en y = 0
    thirdRoom.root.updateMatrixWorld(true)
    const box = new THREE.Box3().setFromObject(thirdRoom.parts.paredes)
    holder.position.set(-(box.min.x + box.max.x) / 2, -box.min.y - 0.02 * ROOM_SCALE, -(box.min.z + box.max.z) / 2)
    thirdRoom.root.updateMatrixWorld(true)
    box.setFromObject(thirdRoom.parts.paredes)
    Object.assign(ROOM, { x0: box.min.x, x1: box.max.x, z0: box.min.z, z1: box.max.z, h: box.max.y })

    // los muros que dan a la camara (x+ y z+) y el techo se recortan (las paredes y el piso)
    ;[thirdRoom.parts.paredes, thirdRoom.parts.piso].forEach((part) =>
        part.traverse((o) => {
            if (!o.isMesh) return
            o.material = o.material.clone()
            o.material.clippingPlanes = [
                new THREE.Plane(new THREE.Vector3(-1, 0, 0), ROOM.x1 - 0.32), // quita lo que pase de x1 - 0.32
                new THREE.Plane(new THREE.Vector3(0, 0, -1), ROOM.z1 - 0.32),
                new THREE.Plane(new THREE.Vector3(0, -1, 0), ROOM.h - 0.12),
            ]
        }),
    )

    // La puerta (marco puerta1.002 y hoja puerta1.001) viene en el .glb con su animacion; el armario, con las de sus hojas.
    // Cada clip se coloca con setThirdDoor(k) / setWardrobe(k).
    const doorBox = new THREE.Box3().setFromObject(thirdRoom.parts.puerta1002)
    Object.assign(DOOR, { x: (doorBox.min.x + doorBox.max.x) / 2, z: (doorBox.min.z + doorBox.max.z) / 2, w: doorBox.max.z - doorBox.min.z, h: doorBox.max.y })
    thirdRoom.mixer = new THREE.AnimationMixer(scene)
    const doorClip = gltf.animations.find((clip) => clip.tracks[0].name.startsWith('puerta1001.'))
    // (del armario se usa un clip por hoja: el .glb trae dos para la hoja derecha y se mezclarian)
    const wardrobeClips = ['Cube.007Action', 'Cube.010Action'].map((name) => gltf.animations.find((clip) => clip.name === name)).filter(Boolean)
    const hold = (clip) => {
        const action = thirdRoom.mixer.clipAction(clip)
        action.play()
        action.paused = true
        return action
    }
    thirdRoom.wardrobeActions = wardrobeClips.map(hold)
    thirdRoom.doorAction = doorClip ? hold(doorClip) : null
    setWardrobe(0)
    setThirdDoor(0)
    installColliders()
    world.root.add(thirdRoom.root)
    lampLight.position.set(0, 2.3, 0.2) // la luz calida de la lampara, al centro del cuarto
    // Luces: si el .glb trae luces (Blender, con la opcion de luces puntuales al exportar) se usan SOLO esas; si no, las de abajo, con un
    // ambiente de noche acogedora: lamparas calidas (naranja rosado) contra sombras frias de tono lila.
    const fileLights = []
    scene.traverse((o) => o.isLight && fileLights.push(o))
    if (fileLights.length) {
        fileLights.forEach((light) => {
            light.intensity *= light.isSpotLight ? 1 / 70 : 1 / 600 // (Blender las exporta en candelas: se llevan a la escala de esta escena)
            light.castShadow = true
            light.shadow.intensity = 0.7
            light.shadow.radius = 2.5
            light.shadow.bias = -0.0005
            light.shadow.normalBias = 0.03
            if (light.isSpotLight) registerExterior(light)
            else registerInterior(light)
        })
    } else {
        // lampara del techo, calida y amplia (alumbra el cuarto desde arriba: muebles, piso y mascotas)
        const ceilingLight = new THREE.PointLight('#ffb98c', 0.12 * LIGHT_SCALE, 8, 0)
        ceilingLight.position.set(0, ROOM.h - 0.3, 0)
        thirdRoom.root.add(registerInterior(ceilingLight))
        // un foco calido que proyecta sombras al piso: muebles, mascotas y personaje (como la sombra del sol, pero desde arriba)
        registerInterior(createCeilingSpot(thirdRoom.root, ROOM.x0 + 0.9, ROOM.h - 0.35, ROOM.z0 + 0.9, 0.5 * LIGHT_SCALE, [0.4, 0.4], '#ffd0a8'))
        // dos toques de color suaves: un resplandor rosado junto a la cama y otro azulado de la computadora
        const bedGlow = new THREE.PointLight('#ff9d8a', 0.07 * LIGHT_SCALE, 3.2, 0)
        bedGlow.position.set(1.0, 1.3, -1.9)
        const screenGlow = new THREE.PointLight('#8fb4ff', 0.06 * LIGHT_SCALE, 2.6, 0)
        screenGlow.position.set(1.7, 1.0, 2.0)
        thirdRoom.root.add(registerInterior(bedGlow), registerInterior(screenGlow))
    }
    thirdRoom.loaded = true
}
/** Abre el armario: k = 0 cerrado, 1 abierto (las hojas animadas del .glb). */
export function setWardrobe(k) {
    const open = Math.min(1, Math.max(0, k))
    thirdRoom.wardrobeActions.forEach((action) => {
        action.time = WARDROBE_CLOSED_AT_START ? open * action.getClip().duration : (1 - open) * action.getClip().duration
    })
    if (thirdRoom.mixer) thirdRoom.mixer.update(0)
}

/** Coloca la hoja de la puerta: k = 0 cerrada, 1 abierta del todo (la animacion del .glb). */
export function setThirdDoor(k) {
    const action = thirdRoom.doorAction
    if (!action) return
    action.time = Math.min(1, Math.max(0, k)) * action.getClip().duration
    thirdRoom.mixer.update(0)
}
/** Muebles que estorban al caminar (x0, x1, z0, z1 en metros): sustituyen a los de la casa de cajas. */
const FURNITURE = [
    [1.3, 2.35, -2.9, -0.95], // la cama
    [-0.5, 0.85, -2.9, -2.25], // la mesa
    [-1.15, -0.6, -2.65, -2.15], // banquito
    [0.35, 0.85, -2.1, -1.6], // banquito
    [-2.4, -1.8, 1.3, 2.9], // el armario
    [0.27, 2.4, 1.12, 2.95], // el escritorio (con la computadora al fondo y la silla debajo)
    [-2.25, -1.8, -1.7, -1.25], // la planta
]
function installColliders() {
    world.colliders.length = 0
    FURNITURE.forEach(([x0, x1, z0, z1]) => world.colliders.push({ x0, x1, z0, z1 }))
}

