/**
 * JUGADOR: teclado/joystick, movimiento, colisiones con los muebles.
 */
import * as THREE from 'three'
import { state } from '../core/state.js'
import { angleDiff, clamp, damp } from '../core/utils.js'
import { quake } from './quake.js'
import { tour } from './scrollTour.js'
import { person } from '../three/characters.js'
import { ROOM, thirdRoom } from '../three/thirdRoom.js'
import { world } from '../three/world.js'

export const player = {
    pos: new THREE.Vector3(0, 0, 3.5),
    yaw: 0,
    pitch: 0,
    moving: false,
    vx: 0,
    vz: 0,
    walked: 0,
    face: 0,
    bob: 0,
}
export const keys = new Set()
export const joystick = {
    x: 0,
    y: 0,
}
const hallDoorBlock = {
    x0: -7.3,
    x1: -7,
    z0: -0.5,
    z1: 1.5,
}
function collide(pos) {
    if (thirdRoom.loaded) {
        pos.x = clamp(pos.x, ROOM.x0 + 0.4, ROOM.x1 - 0.4)
        pos.z = clamp(pos.z, ROOM.z0 + 0.4, ROOM.z1 - 0.4)
    } else {
        pos.x = clamp(pos.x, world.hallOn ? -13 : -6.6, 6.6)
        pos.z = clamp(pos.z, -4.6, 4.6)
    }
    let a = (o) => {
        let s = clamp(pos.x, o.x0, o.x1),
            r = clamp(pos.z, o.z0, o.z1),
            i = pos.x - s,
            n = pos.z - r,
            d = i * i + n * n
        if (d < 0.35 * 0.35)
            if (d > 1e-6) {
                let u = Math.sqrt(d)
                pos.x = s + (i / u) * 0.35
                pos.z = r + (n / u) * 0.35
            } else {
                let u = pos.x - o.x0,
                    h = o.x1 - pos.x,
                    p = pos.z - o.z0,
                    E = o.z1 - pos.z,
                    L = Math.min(u, h, p, E)
                if (L === u) {
                    pos.x = o.x0 - 0.35
                } else if (L === h) {
                    pos.x = o.x1 + 0.35
                } else if (L === p) {
                    pos.z = o.z0 - 0.35
                } else {
                    pos.z = o.z1 + 0.35
                }
            }
    }
    world.colliders.forEach(a)
    if (!world.hallOn && !thirdRoom.loaded) {
        a(hallDoorBlock)
    }
}
export function resetPlayer(x, z, yaw) {
    player.locked = false
    player.pos.set(x, 0, z)
    player.yaw = yaw || 0
    player.pitch = 0
    player.walked = 0
    player.vx = 0
    player.vz = 0
    player.face = Math.PI * 0.75
}
/** Mueve al jugador cada cuadro segun teclado/joystick, el modo de camara y el sismo. */
export function updatePlayer(dt) {
    if (state.mode !== 'fp' && state.mode !== 'tp') return
    if (tour.active) return // en el recorrido por scroll la camara la mueve scrollTour.js
    const down = (code) => keys.has(code)

    // Ejes de entrada: forward (adelante +) y strafe (derecha +)
    let forward =
        (down('KeyW') || down('ArrowUp') ? 1 : 0) - (down('KeyS') || down('ArrowDown') ? 1 : 0) - joystick.y
    let strafe = (down('KeyD') ? 1 : 0) - (down('KeyA') ? 1 : 0) + joystick.x
    if (state.mode === 'tp') {
        strafe += (down('ArrowRight') ? 1 : 0) - (down('ArrowLeft') ? 1 : 0)
    } else {
        player.yaw += ((down('ArrowLeft') ? 1 : 0) - (down('ArrowRight') ? 1 : 0)) * dt * 1.9
    }
    if (player.locked) {
        forward = 0
        strafe = 0
    }
    const len = Math.hypot(forward, strafe)
    if (len > 1) {
        forward /= len
        strafe /= len
    }

    // Velocidad: algo mas lenta durante el sismo
    let speed = state.mode === 'fp' ? 3.1 : 4.4
    if (quake.active) {
        speed *= 0.9
    }

    // Direccion en el mundo: primera persona sigue la camara, tercera persona es isometrica
    let dirX, dirZ
    if (state.mode === 'fp') {
        dirX = -Math.sin(player.yaw) * forward + Math.cos(player.yaw) * strafe
        dirZ = -Math.cos(player.yaw) * forward - Math.sin(player.yaw) * strafe
    } else {
        dirX = (-forward + strafe) * 0.7071
        dirZ = (-forward - strafe) * 0.7071
    }
    // Aceleracion y freno suaves: el personaje arranca y se detiene sin tirones (WASD y flechas por igual)
    const pushing = len > 0.06
    const rate = pushing ? 16 : 22
    player.vx = damp(player.vx, pushing ? dirX * speed : 0, rate, dt)
    player.vz = damp(player.vz, pushing ? dirZ * speed : 0, rate, dt)
    const pace = Math.hypot(player.vx, player.vz)
    player.moving = pace > 0.35
    if (player.moving) {
        const px = player.pos.x
        const pz = player.pos.z
        player.pos.x += player.vx * dt
        player.pos.z += player.vz * dt
        collide(player.pos)
        const moved = Math.hypot(player.pos.x - px, player.pos.z - pz)
        // si un mueble lo frena, pierde esa velocidad en vez de quedarse "pegado" empujando
        if (moved < pace * dt * 0.5) {
            player.vx *= 0.5
            player.vz *= 0.5
        }
        player.walked += moved
        player.bob += dt * (state.mode === 'fp' ? 9 : 12) * Math.min(1, pace / speed + 0.3)
        if (state.mode === 'tp') {
            player.face += angleDiff(player.face, Math.atan2(player.vx, player.vz)) * Math.min(1, dt * 14)
        }
    }

    // Animacion del personaje en tercera persona
    if (state.mode === 'tp') {
        person.position.set(player.pos.x, 0, player.pos.z)
        person.rotation.y = player.face
        const swing = player.moving ? Math.sin(player.bob) * 0.7 : 0
        const limbs = person.userData
        limbs.walking = player.moving // (el personaje con huesos camina solo)
        limbs.legL.rotation.x = swing
        limbs.legR.rotation.x = -swing
        limbs.armL.rotation.x = -swing * 0.8
        limbs.armR.rotation.x = swing * 0.8
        person.scale.y = damp(person.scale.y, 1, 14, dt)
    }
}
